INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shin-megami-tensei-devil-collection', 147169, '2013-08-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zy5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9iy3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Devil Collection', 'Devil Collection is a social card-battling game released through the Mobage service. Like other social games on the service, it is based on a free-to-play model. The story centers around players defending modern day Tokyo from a demonic invasion as a demon summoner with access to demon summoning and fusion through a cellphone application. By gathering demon companions and fusing them with customized skillsets, players are able to organize them into decks. Card rarity levels are denoted by the star values on the side of each card with Master, the highest ranking, being six stars. The game hosts regular events featuring card prizes, such as the gift of a Super Rare-level Cerberus card for pre-registration and a Snow Wars event focused on the Jack family with the introduction of the King Frost card.' FROM games WHERE igdb_id = 147169 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 147169 AND ge.slug = 'card-and-board-game' ON CONFLICT DO NOTHING;
