INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9iy3.jpg', 0, true FROM games WHERE igdb_id = 147169 ON CONFLICT DO NOTHING;
INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9iy4.jpg', 1, false FROM games WHERE igdb_id = 147169 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('luxor-2-hd', 30226, '2013-02-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pyh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sgct1xpkcxrluk2hltzv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luxor 2 HD', 'The much anticipated sequel to the #1 casual game of 2005, LUXOR 2 HD has been re-imagined and sets the new standard for action-puzzlers with dazzling new HD graphics & effects. Luxor 2 HD still offers the addictive and easy-to-learn, yet difficult to master game play which made the award-winning Luxor franchise such a smash hit, while taking the game to a completely new level. Luxor 2 HD takes you on a beautiful voyage through the land of ancient Egypt. Play 88, gorgeously rendered levels in brilliant, widescreen HD graphics set amongst the pyramids and temples of ancient Egypt. Use your mystical winged scarab to shoot and destroy the approaching magical spheres before they reach the pyramids at the end of their path. And to help you shoot down those enemy spheres, Luxor 2 HD features more explosive power-ups than ever before. Key Game Features 88 explosively challenging levels with 26 re-mastered HD Widescreen Backgrounds Spectacular new Visual Effects throughout Four invigorating levels of difficulty, including the expert level that unlocks the mind-blowing Challenge of Horus Over 80 statistics and badges, plus bonus rounds at the end of each stage Ranking system to let players work their way from Farm Hand to Pharaoh Three stimulating modes of play, including the Survival and Practice modes 13 explosive and unique power-ups, including the Color Cloud, Net, Dagger and Lightning Storm, to help destroy the oncoming enemy spheres 13 intense and rewarding bonus rounds at the end of each stage in the game' FROM games WHERE igdb_id = 30226 ON CONFLICT (game_id, language_code) DO NOTHING;
