INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panda Pop: Bubble Shooter', 'The best bubble shooter game! Blast bubbles, save baby pandas! Play now for free! Plan your every pop to rescue cute baby pandas! An evil baboon has kidnapped & trapped precious panda pups in the jungle. Blast, match, and pop bubbles to help beat him & return the cubs to their worried mother! Work your way through increasingly challenging puzzles and employ the power of the elements to help you in your Panda Pop quest. Use epic bubble shooter power ups to free the pups… combine them for even greater effect!' FROM games WHERE igdb_id = 87039 ON CONFLICT (game_id, language_code) DO NOTHING;
