INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Shinkirou: Hopeless Masquerade', 'Hopeless Masquerade is a one-on-one aerial fighter with no ground combat. The game takes place somewhere between Ten Desires and Double Dealing Character. Characters fight one another by using standard attacks (melee and special attacks), skills, and spell cards. Each character features a unique fighting style. Spell cards, skill cards, and items are "declared" by inputting a particular button combination.' FROM games WHERE igdb_id = 27158 ON CONFLICT (game_id, language_code) DO NOTHING;
