INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shattered-haven', 9407, '2013-03-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jmb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21lv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shattered Haven', 'Grays roam the land, largely in the absence of human interference. These aren''t your typical Zed -- theirs is a very different sort of apocalypse. Animals spontaneously transform into twisted, violent beings. The earth decays, collapsing into a network of abysses. The wilderness thickens. It has been nine years since That Day when it all started. Pockets of humanity still exist, but are ignorant of one another. Within these isolated havens people try to live as best they can -- for even in a world so broken and dark, daily life must go on. Darrell and Mary Williams were able to build such a life inside a five-acre fenced yard out in the country. They were even secure enough in their isolated compound that they had a daughter five years after the zombie-like grays appeared. Life carried on as normally as it could, until another refugee on the run is killed during a nearby attack. Her son is saved and taken in by the Williamses -- who do not realize that this kind action will destroy their home and threaten their entire family. They find themselves caught in the midst of a struggle between two eldritch horrors, and the path to survival is anything but clear.' FROM games WHERE igdb_id = 9407 ON CONFLICT (game_id, language_code) DO NOTHING;
