INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yume Aruki', 'Yume Aruki is a traditional Yume Nikki fangame. The main objective is exploring Twill''s dreams and collecting effects. Notably absent from this game are aggressive NPCs, extensive events, and the horror overtones from both Yume Nikki and its many fangames. The game draws heavily on animal, tropical, and desert imagery.' FROM games WHERE igdb_id = 166464 ON CONFLICT (game_id, language_code) DO NOTHING;
