INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Driftkhana', 'Built with freedom in mind, there are no point systems, time limits, or rules simply because when it comes to cars and drifting, you should be free to do whatever you want! Driftkhana lets you drift till your heart''s content, interacting with a variety of objects within the set. Moveable ramps, giant road cones and beach balls are but a few of the fun props you''ll find yourself skidding around.' FROM games WHERE igdb_id = 197345 ON CONFLICT (game_id, language_code) DO NOTHING;
