INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sound-voltex-ii-infinite-infection', 39859, '2013-06-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nssetrq5vs95t1vmm6tq.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sound Voltex II: Infinite Infection', 'The game was released as an online update, one of the first BEMANI titles to do so.  Data carrying over from SOUND VOLTEX BOOTH consists of: player name (changeable), scores, clear marks, unlocked songs and play count of songs.  There are now hold notes on short buttons (LONG BT) and non-hold notes on long buttons (CHIP FX).  FX hold notes are now orange instead of dark green.  The song select screen was redesigned to go from a song wheel to a grid of jackets.  The INFINITE difficulty is introduced, similar to DanceDanceRevolution''s CHALLENGE difficulty in nature. INFINITE charts have a rainbow hue.  PERFECT ULTIMATE CHAIN (getting 100% CRITICALs) has been renamed "PERFECT".  Similar to its beatmania IIDX counterpart, the "green number" (BPM x HI-SPEED value) feature has been added.  Failing songs with charts that have a difficulty rating of 7 or lower will not end your game session prematurely.  Charts rated Level 16 have been introduced.  Songs are divided into eight categories:  ALL (unsorted).  BEMANI (all remixed and original BEMANI songs).  EXIT TUNES (EXIT TUNES licenses).  ボーカロイド™ (all VOCALOID songs).  FLOOR (original FLOOR contest songs).  SDVXオリジナル (original SOUND VOLTEX songs).  東方アレンジ (Touhou Project licenses and remixes).  BLASTER (related to INFINITE BLASTER).' FROM games WHERE igdb_id = 39859 ON CONFLICT (game_id, language_code) DO NOTHING;
