INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell: Blacklist - 5th Freedom Edition', 'Sam Fisher is back and operating without restrictions in a thrilling plot fitting for the master of modern espionage. New gameplay features including Killing in Motion. Unleash the power of 4th Echelon Prototypes and build a new Echelon and enjoy a fully integrated experience aboard the Paladin. The Splinter Cell Blacklist 5th Freedom Edition contains: - 24cm Sam Fisher Figurine - Steelbook - Collector Box - 96 page Splinter Cell Echoes Graphic Novel - Single and multiplayer coop maps: Dead Coast and Billionaire''s Yacht Unlockable gear: - 5 pieces of gear: Gold and Amber goggles, Ghost Boots, Armored Boots and Tactical Gloves - 5 suits: The Elite Digital Ghillie Suit, Spy Suit, Mercenary Suit, Upper Echelon Suit and Eclipse Suit - 5 weapons: VSS Sniper Rifle, M1014 Tactical Shotgun, HK 416 Assault Rifle, F40 Pistol and Crossbow' FROM games WHERE igdb_id = 44568 ON CONFLICT (game_id, language_code) DO NOTHING;
