INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell: Blacklist - Digital Deluxe Edition', 'Tom Clancy''s Splinter Cell Blacklist Deluxe Edition comes with all the essential weapons, gadgets, and gear for you to become Sam Fisher and stop the escalating Blacklist threats. With two bonus missions and five bonus suits, armor upgrades, and weapons, you''ll be prepared to stop the attacks! Content Includes: - The High Power DLC Pack: - AC S12 Shotgun - GC36C Assault Rifle - MP5-10 SMG - PP-19 Black Market SMG - USP45 Hand Gun' FROM games WHERE igdb_id = 53944 ON CONFLICT (game_id, language_code) DO NOTHING;
