INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cold Case Summer', 'Cold Case Summer is the ninth game in the long-running series of first-person adventure games from developer MDNA games. This is a point-and-click adventure game that involves exploring for clues and inventory items, as well as solving logic and inventory-based puzzles. The game''s artwork is made from still photographs taken in Sweden, with node-based movement. As with previous games in the series, there is voice acting and background music. There is a new hotspot revealer making it somewhat easier to locate items of interest.' FROM games WHERE igdb_id = 151544 ON CONFLICT (game_id, language_code) DO NOTHING;
