INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Kindness is Not an Invitation For You to Touch Me', 'I made this game in 2013 after I went to PAX East, where a dude I''d just met in person pissed all over my personal boundaries and slam dunked them into a trash can. I was angry and this helped me feel much better!' FROM games WHERE igdb_id = 128743 ON CONFLICT (game_id, language_code) DO NOTHING;
