INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Tribe 2', 'Alien Tribe 2 is an indie 4x space game that combines several genres. Imagine a universe sandbox meets real-time strategy and a pinch of tower defense and Master of Orion. The 4X stands for "eXplore", "eXpand", "eXploit" and "eXterminate", and Alien Tribe 2 offers all these different strategies for the player - from exploring the galaxy to extracting raw materials or fending off hostile attacks.' FROM games WHERE igdb_id = 97309 ON CONFLICT (game_id, language_code) DO NOTHING;
