INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pepi Doctor', 'Need help to calm your kids before seeing a doctor? Try talking to a child, while playing! Pepi Doctor is updated and ready to meet new patients! Is your kid afraid of the doctors? What about dentists? Get some help from a child-friendly PEPI DOCTOR! Enjoy this cheerful pretend play game where a child plays a Doctor and treats three little patients: Amber, Eva and Milo. It’s easy and fun to be a Doctor in this game: kids will explore a variety of doctors’ tools and get to cure five different conditions at their own pace.' FROM games WHERE igdb_id = 343994 ON CONFLICT (game_id, language_code) DO NOTHING;
