INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Another World', 'The Jaguar port of Another World was meant to be released by Interplay in 1994, but ended up being cancelled. It was later updated and released version in 2013 and is playable in the original graphics 16-color mode and Deluxe 15th Anniversary graphics 256-color mode. It can be played in normal and speed-run modes.' FROM games WHERE igdb_id = 343435 ON CONFLICT (game_id, language_code) DO NOTHING;
