INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brawlin'' Sailor', 'Brawlin'' Sailor is a short beat ''em up game which tells a humorous story about dreams and reality. The player controls a strapping sailor who receives a letter from a damsel in distress, locked in a lighthouse on a "seckrit island" by ferocious pirates. The goal is to make it to the lighthouse, beating up the enemies and bosses encountered on the way.' FROM games WHERE igdb_id = 201288 ON CONFLICT (game_id, language_code) DO NOTHING;
