INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('greed-city', 341900, '2013-03-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qlz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3k69.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Greed City', 'Are you ready to climb to the top of the business world and become the ultimate property tycoon? Look no further than Greed City, the multiplayer online game where players use real-world locations and check-ins to build their empires and earn credits. With strategy as the key to success, you can grow your monopoly with some of the world''s most iconic landmarks and locations. In this cutthroat game, you''ll have the opportunity to set up new businesses or steal existing ones from your competitors. Use cards to ruin a business''s value and outmaneuver the competition. Plus, earn diamonds, cards, and extra credits when you check into other businesses using your phone''s GPS. But that''s not all – in Greed City, you can own all your favorite stadiums, landmarks, airports, and cities. Upgrade your businesses to attract new customers and watch your profits soar as you rise to the top. Invite your friends to play and compete in monthly tournaments. The location is key in this game of ruthless real estate tycoons – will you become the next Jobs, Gates, or Musk? Download Greed City now and find out!' FROM games WHERE igdb_id = 341900 ON CONFLICT (game_id, language_code) DO NOTHING;
