INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skateboard-3d-skater-die-hard-skate-boarding-game', 98901, '2013-05-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5jb1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjedy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skateboard 3D - Skater Die Hard Skate Boarding Game', 'Skateboarding 3D is a perfect entertainer game for all ages to have an unlimited fun to do simple to complex tricks in all kinds of skating objects and terrains. Roam the mega city skyscraper streets with your long skateboard and exhibit skating skills in riverside skate park. Not satisfied, Need more ? Try fast pedaling in regular and beautiful pro skate park arena with water fountain and tunnel where number skating objects is inviting you perform do or die tricks. Don''t miss the egg plant mount and wooden and concrete slabs blocks for funny tricks. You can associate yourself with one of the four 3D animated skaters to collect various gifts like googles, cap, t-shirt, skateboards, shoes and coins within limited time window frame based on your level selection. Amazing four different theme park area with perfect mobile skater animations like pedaling, jump, ollie & flips etc. Three different teen boys and one girl to choose from with an option of playing it with motion sensor or easy touch joystick or old style D-pad controls. Collect as many gifts and brag to others about your achievements. Learn to control the skater with your touch, eye and motion controls to win as many gifts as you can. Fun starts here and never stops with superb background music blended with wheels, decks and landing gear makes it own grinding noise.' FROM games WHERE igdb_id = 98901 ON CONFLICT (game_id, language_code) DO NOTHING;
