INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dooors 2', 'This is the sequel of "DOOORS"; the stage clear-type escape game hit over 15,000,000 downloads. The purpose of this game is to break out of the rooms. Solve the hidden mysteries by making full use of iPhone gestures, such as shake or multi-touch, and complete all the stages! ● Game Features - 60 new stages - Mini escape games that are perfect to kill your free time - Stunning graphics - Auto-save' FROM games WHERE igdb_id = 383575 ON CONFLICT (game_id, language_code) DO NOTHING;
