INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Press-Switch', 'Press-Switch is a visual novel that follows an innocuous high school boy by the name of Calvin Hintre, whose life changes dramatically when he finds finds himself in possession of a device known as the DSM. An enigmatic doohickey capable of body swapping, mind control, transformation, possession, gender bending, and more. This naturally opens up a vast array of opportunities to Calvin, allowing him to turn his relatively humdrum life into something far more exciting… and potentially devastating.' FROM games WHERE igdb_id = 217993 ON CONFLICT (game_id, language_code) DO NOTHING;
