INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Fist Ninja Run Challenge', 'This runner game is filled with action and pure adrenalin. Story mode: To survive the first challenge you need to be faster than the ghosts of the north - so run, jump and fight against different enemies. Collect coins to buy helpful items in the store. Black Fist Ninja Run Challenge is completely free to play, but in-game items can also be purchased for real money, like the arcade modes for endless fun. Try the endless runner game or the fight training (swordplay and archery).' FROM games WHERE igdb_id = 175576 ON CONFLICT (game_id, language_code) DO NOTHING;
