INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'First! Person Shooter', 'A game made for 7DFPS 2013. YouTube is littered with people commenting "FIRST!", so obliterate them in the fast paced shooter "FIRST! Person Shooter." Sort through comments on a quest to cleanse YouTube, while trying not to delete useful comments. Graphics by yours truly, music by Kevin MacLeod used under a Creative Commons License.' FROM games WHERE igdb_id = 333228 ON CONFLICT (game_id, language_code) DO NOTHING;
