INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World''s End Chapter 1', 'A darkly comedic turn-based strategy RPG. Learn skills to improve strengths and unlock special attacks and abilities. Buy, find and plunder items and equipment. Use terrain, traps, obstacles and even foes'' corpses to gain the tactical advantage as you lead Tevoran and Company to questionable victory.  Features  Morally ambiguous heroes, dubious enemies and an unconventional story  Turn-based, tactical combat  6 player characters with unique skills and equipment  Dynamic terrain including traps, shoving and moveable obstacles  5+ hours of gameplay  Original, hour-long soundtrack  Progress carries over to Chapter 2' FROM games WHERE igdb_id = 143811 ON CONFLICT (game_id, language_code) DO NOTHING;
