INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('timepiece-ensemble', 216242, '2013-12-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kog.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvulj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timepiece Ensemble', 'It’s the day before Hourai Shinobazu Academy’s culture festival. Taki and the rest of the Pip Club’s members are busy preparing their booth. On to way to the discount store to buy some last-minute supplies, he came upon a new store in a back alley called Kikouya (House of Tricks). Entering the shop, he was greeted by a talking cat Tetmet who took his order and brought him everything he needed, and at a bargain too. When he was about to leave, the storeowner Kuroha asked him if he would like to ‘buy time’. He was perplexed at her question, but was too worried about finishing up the club’s booth for the culture festival, muttering that ‘if he only had one more day, then everything would be done in time’. “Thank you, please come again,” said Kuroha as he left. As expected, there wasn’t enough time for them to finish their preparations, so the club members all stayed overnight at the school to finish up. Although some parts were still not completely done, they planned to give it their all. When they woke up, they began their preparations for the culture festival the next day. An extra day had been added due to Taki’s wish, and he was the only one who realized it.' FROM games WHERE igdb_id = 216242 ON CONFLICT (game_id, language_code) DO NOTHING;
