INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Will You Press the Button?', 'You are presented with a red button and two scenarios: one good and one bad. Both will happen if you Press The Button. Will You Press The Button? The choice is yours. Do you like to play games that make you think, laugh, and question your choices? If yes, then you will love Will You Press The Button? - the ultimate game of moral dilemmas!' FROM games WHERE igdb_id = 326717 ON CONFLICT (game_id, language_code) DO NOTHING;
