INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flatout: Stuntman', 'Have a take-off run with one of the many types and sorts of vehicles, launce your handpicked character (out of many, one even crazier as the other) and proceed to aim for the objects that will do you the most damage... thus earning you the most points! Try and take some coins along the way. Ragdoll fun for everone! This contains a ton of different and fun themes, stunts, plenty of vehicles and numerous characters to have fun with.' FROM games WHERE igdb_id = 309217 ON CONFLICT (game_id, language_code) DO NOTHING;
