INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell: Blacklist - Ultimatum Edition', 'The United States has a military presence in two-thirds of countries around the world, and some of them have had enough. A group of terrorists calling themselves The Engineers initiate a terror ultimatum called the Blacklist - a deadly countdown of escalating attacks on U.S. interests. Ultimatum Edition Includes: - Special-Ops Digital Watch. - Soft Touch Collector Box. - 24 page Splinter Cell Echoes Graphic Novel. - Single and multiplayer coop maps: Dead Coast and Billionaire''s Yacht. Unlockable gear: - 2 pieces of gear: Gold goggles and Ghost Boots - 1 suit: Upper Echelon Suit' FROM games WHERE igdb_id = 42971 ON CONFLICT (game_id, language_code) DO NOTHING;
