INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ningyo Heart', 'Ami and Mamoru are two childhood friends, until, one day, Mamoru starts suffering heart problems and ends up in a coma. Miraculously, Mamoru manages to wake up, but to his surprise, his friend Ami is missing. Knowing that something bad is happening, he begins to investigate, and all the clues lead him to the "Dollmaker".' FROM games WHERE igdb_id = 151814 ON CONFLICT (game_id, language_code) DO NOTHING;
