INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Injustice: Gods Among Us - Collector''s Edition', 'The US version of the Collector''s Edition includes: - Injustice: Gods Among Us video game - Exclusive 12" (30 cm.) figurine statue featuring Batman and Wonder Woman - Official DC Comic Book “Injustice: Gods Among Us” details the events leading up to Injustice: Gods Among Us video game - 3 exclusive skins based on Batman, Superman and Wonder Woman from DC COMICS – THE NEW 52 - Digital download copy of DOOM: JUSTICE LEAGUE movie The EU version of the Collector''s Edition includes: - Steelbook case version of the Injustice: Gods Among Us video game Collector''s Box - Exclusive 9" (23 cm.) figurine statue featuring Batman and Wonder Woman - Official DC Comic Book “Injustice: Gods Among Us” details the events leading up to - Injustice: Gods Among Us video game - 3 exclusive skins based on Batman, Superman and Wonder Woman from DC COMICS – THE NEW 52' FROM games WHERE igdb_id = 75426 ON CONFLICT (game_id, language_code) DO NOTHING;
