INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Mini Dino Hunter', 'Dinosaurs emerge from the ancient forest after hiding for decades. As a descendant from a great hunter family, you continuously hone skills towards your desired goal in order to stand up to your father''s expectation. Now it''s time to prove yourself. Fight your way through hordes of giant lizards and collect items to craft and upgrade various weapons.' FROM games WHERE igdb_id = 348481 ON CONFLICT (game_id, language_code) DO NOTHING;
