INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Max Axe', 'Tired of lame-axe games? Get ready for MAX AXE! Throw axes with your finger to slay foul beasts, collect REDONKULOUS treasure and score BILLIONS of points to outrank your friends! Max Axe blends 100% pure arcade frenzy with humor, crazy combos, and absolutely bonkers high-speed action like nothing you''ve ever seen before. Take on the role of Max, a Viking barbarian berserker on a quest for total destruction, massive loot and of course, princesses!' FROM games WHERE igdb_id = 343970 ON CONFLICT (game_id, language_code) DO NOTHING;
