INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva Arcade Future Tone', 'The sequel to Hatsune Miku: Project Diva Arcade, adding several new songs and a Touch Slider. It also features improved graphics over the previous game thanks to upgraded hardware powering the game. The game received two major updates, "Version A" and "Version B", which each added new songs. It also received a cabinet revision that added a photo mode and a printer to print photos taken, titled "Hatsune Miku: Project Diva Arcade Future Tone with Photo Studio". Hatsune Miku: Project Diva Arcade Future Tone was ported to the PlayStation 4 in 2016 as "Hatsune Miku: Project Diva Future Tone".' FROM games WHERE igdb_id = 178136 ON CONFLICT (game_id, language_code) DO NOTHING;
