INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Manic Miner Man', 'Pac-Manic Miner Man was written in 2012 by Jim Bagley to run the classic ZX Spectrum Game Manic Miner on Pac-Man Arcade hardware, a long time ambition of his was to write an arcade game on arcade hardware but little did he know he would eventually write a game that would run on Pac-Man hardware. After finding the memory map for Pac-Man he decided the opportunity was too good to miss and as a tribute to the classic ZX Spectrum game he wrote Pac-Manic Miner Man as it fit the constraints of the hardware.' FROM games WHERE igdb_id = 38610 ON CONFLICT (game_id, language_code) DO NOTHING;
