INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kochiya Sanae no Kamikaze to Tomo ni', 'The gameplay consists of action, platform, small puzzle solving elements and boss battle at the end of each stage. Sanae has Kirby''s signature method of dispatching enemies by using the ability of inhaling with extreme power. By pressing X button repeatedly, Sanae is able to fly for as long as she likes to reach higher platforms or to find secret item locations.' FROM games WHERE igdb_id = 165524 ON CONFLICT (game_id, language_code) DO NOTHING;
