INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic Pirates Story', 'On your journey you will have to master difficult battles with barracudas, mermaids, strange undead, monkeys, Indians and fearsome pirates. You start on an lonely island with a small boat. Over time your party and town grow until you are powerful enough to encounter A.Blizzardo. Gather powerful weapons, build crazy buildings, hold funny events and become the pirate king.' FROM games WHERE igdb_id = 200019 ON CONFLICT (game_id, language_code) DO NOTHING;
