INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bewilder House', 'Bewilder House is a first-person puzzle game where you have to overcome a feeling of loss of bearings. Trapped in strange mazes where the walls open and close when you''re not looking, you''ll have to use your mind and first person controls in unusual ways to escape a deceptive funhouse that plays with both your perception, and your life.' FROM games WHERE igdb_id = 229534 ON CONFLICT (game_id, language_code) DO NOTHING;
