INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sinjid', 'Sinjid is the third game in the Sinjid series. It is a role-playing action-adventure game with real time battles made for flash. In this game, players take control of the eponymous protagonist, Sinjid and unfolds his story.  Features:  - Play as 3 different classes!  - Action packed RPG adventure!  - Over 300 items and equipment!  - Nine epic zones to explore!  - Nine epic bosses to defeat!' FROM games WHERE igdb_id = 57015 ON CONFLICT (game_id, language_code) DO NOTHING;
