INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Woo''s Twisted Clone Shop', 'Pixel Farm wanted to build a mobile game division. We created a department of talented mutants and made Dr. Woo’s Twisted Clone Shop. It''s a puzzle/matching game in which you attempt to clone various animals, anything from a gold fish to a unicorn. Work your way through over a dozen genetic experiments, but watch out for mutations and other stuffs.' FROM games WHERE igdb_id = 343996 ON CONFLICT (game_id, language_code) DO NOTHING;
