INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Highway: Driver''s Ed', 'Driver''s Ed is a spinoff of Zombie Highway that puts your driving skills to the test. Complete scored runs on a zombie filled driving course. Watch your skills improve and scores increase as you rack up cash to buy upgrades for your car and other gadgets! String together epic combos of scrapes, kills and more! But, watch out! Mistakes like scraping a barrier that were once harmless will now end your combo and reduce your score.' FROM games WHERE igdb_id = 344279 ON CONFLICT (game_id, language_code) DO NOTHING;
