INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 6: Ultimate Edition', 'The Resident Evil 6: Ultimate Edition includes the base game and the following bonus downloadable content: - Extra Stages: Requiem for War, Liquid Fire, Rooftop Mission, Creature Workshop, Rail Yard, High Seas Fortress, the Catacombs - Extra Gameplay Modes: Siege Mode, Onslaught Mode, Survivors Mode, Predator Mode' FROM games WHERE igdb_id = 99927 ON CONFLICT (game_id, language_code) DO NOTHING;
