INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Path of the Pumpkin', 'Skar the Pumpkin and his assistant Mr.FeeFee, are two well-know detectives of Treshopolis.  One day, their dreary routine is shattered by an out-of-the-ordinary mission, that will take them on a hunt for a girl who as be kidnapped and forced to marry against her will.  The two "detectives" have to do their utmost, in order to bring the case to a conclusion, but... this is only the beginning of something much bigger and much more involved!' FROM games WHERE igdb_id = 125141 ON CONFLICT (game_id, language_code) DO NOTHING;
