INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airport Simulator 2014', 'Booming turbine noise, kerosene smells in the air and constant change and new challenges: The daily life of a large airport is perfectly presented and is a particular challenge in this professional and economic airport simulation. Whether refueling super jumbos, or coordinating air traffic controllers and technical staff, or even organizing perfect catering: The Management of this airport will always have new challenges for you.' FROM games WHERE igdb_id = 16899 ON CONFLICT (game_id, language_code) DO NOTHING;
