INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die Hard', 'DIE HARD game has been released for the iPhone, iPad, and iPod touch coinciding with the theatrical release of ''A Good Day to Die Hard''. Play as Jack McClane, the son of New York City’s most famous cop, legendary John McClane. Prove that the apple doesn’t fall far from the tree – blast your way out of Moscow’s mean streets and travel to the radioactive wasteland of Chernobyl, where you’ll have to overcome incredible odds to save the world from nuclear terrorism. Combining the best of the “endless runner” genre with non-stop shooter action, you now have the ability to play through one of the most popular action-movie franchises in film history! Keep moving and stay alive as long as you can!' FROM games WHERE igdb_id = 131004 ON CONFLICT (game_id, language_code) DO NOTHING;
