INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gurk III', 'The long-awaited sequel to the also-long-awaited sequel to the beloved 8-bit RPG has finally arrived! The third installment in the series is a bigger adventure than ever before, with loads of new monsters and items, many with unique effects and abilities. Character classes are better-differentiated and combat tactics are more subtle and interesting without sacrificing the hack''n''slash ethos that Gurk fans adore. The dedication to 8-bit culture remains fervent, with the complete 20-song soundtrack rendered with analog synth emulators that will evoke the classic sounds of the game systems of the 1980s.' FROM games WHERE igdb_id = 19126 ON CONFLICT (game_id, language_code) DO NOTHING;
