INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trial', 'Trial is a Japanese Yume Nikki fangame. You take the role of Suzutsuki, a girl who cannot leave her room, thus forcing her to explore her own dreams instead of reality. Trial has an unusually large number of effects compared to most fangames, containing 28 effects.' FROM games WHERE igdb_id = 229402 ON CONFLICT (game_id, language_code) DO NOTHING;
