INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Rocks HD', 'Pinball Rocks HD is a five table compilation featuring a free game loaded with new songs from today''s top rock artists and four custom branded unlocks for Alice in Chains, Bullet For My Valentine and the original critically acclaimed hits AC/DC and Slayer. Each game provides cutting edge 3D graphics, missions, unique bonus games and ear-splitting riffs.' FROM games WHERE igdb_id = 343837 ON CONFLICT (game_id, language_code) DO NOTHING;
