INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ore no Imouto ga Konnani Kawaii Wake ga Nai. HappyenD', 'Ore no Imouto ga Konnani Kawaii Wake ga Nai. HappyenD, shortened as Oreimo HD, is a game for the PlayStation 3 based on the Ore no Imouto ga Konna ni Kawaii Wake ga Nai light novel series, produced by Bandai Namco Games. It was announced during ASCII Media Works'' Dengeki Game Thanksgiving 2013 and Dengeki Bunko Spring Festival 2013 at Akihabara.' FROM games WHERE igdb_id = 62803 ON CONFLICT (game_id, language_code) DO NOTHING;
