INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-clockwork-ley-line-zanei-no-yoru-ga-akeru-toki', 54750, '2013-01-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co312i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvvwo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Clockwork Ley-Line: Zanei no Yoru ga Akeru Toki', 'Follow the story of Koga Michiru as he worked the orders of the Bureau for the Investigation of Special Affairs, or simply called "Bureau", together with his friends as they solve the schools mysteries and problems. Until that day when an unlikely visitor appeared before the school''s doorsteps. In search for her grandmother''s keepsake, she pushed order after order towards the bureau, an unknown foreigner from an unknown country--Adelheid Ritter von Weinberger. "Yes, perhaps we should test their ability." While wrapped up in search for Adelheid''s keepsake, it was as if time started passing by at their command. Is it because of the secret their academy possessed--the Realm of Night? Where were these strangers from? Where will they return to? Follow the secrets and mysteries alongside our heroes and heroines in "Daybreak of Remnants Shadow"!' FROM games WHERE igdb_id = 54750 ON CONFLICT (game_id, language_code) DO NOTHING;
