INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totems: Game of Conquest', 'The game design is derived from the world-famous “4-Color Map Theorem”. The randomness of the totems in your ‘hand’, the changing colors of the territories, the variety of the maps, and the cleverness of your opponents will all conspire to make each turn a fun and interesting challenge.' FROM games WHERE igdb_id = 200188 ON CONFLICT (game_id, language_code) DO NOTHING;
