INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Relic Rush', 'Silver Award Winner from Pocket Gamer! Relic Rush is an addictive adventure game. Use one touch controls to help our fearless hero navigate dangers as he collects the idols. Explore exotic locations like jungles and deserts as you race against the clock. Can you collect them all? - Beautiful Pixel Art - Easy One Touch Controls - Over 100 Levels to explore and navigate - Original Chiptune Soundtrack - 5 Unique Worlds to Adventure through - Retro Sounds' FROM games WHERE igdb_id = 304253 ON CONFLICT (game_id, language_code) DO NOTHING;
