INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Driving Simulator 2013', 'Race for the best time, chase criminals, save lives, tow vehicles and go off-road. Choose your vehicle, start your engine and prepare for a thrilling ride across three European cities.  Whether you want to test your speed in a powered up sports car, save lives in the ambulance missions or just cruise the motorway in the camper van, Driving Simulator 2013 is the full package. You can get behind the wheel of several types of vehicles each with their own special missions and, new for 2013, take part in a European driving school to test your skills on the road.' FROM games WHERE igdb_id = 10249 ON CONFLICT (game_id, language_code) DO NOTHING;
