INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Santa''s Baby Care & Nursery', 'Santa''s Baby Care & Nursery is a casual simulation game designed for young audiences, where players take on the role of Santa’s helper in a magical nursery. The goal is to care for baby elves and other festive characters by feeding, bathing, dressing, and entertaining them in a cozy North Pole setting. With colorful graphics and simple touch-based controls, the game offers a lighthearted holiday-themed experience focused on nurturing and creativity.' FROM games WHERE igdb_id = 99903 ON CONFLICT (game_id, language_code) DO NOTHING;
