INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '13 Page', '13 Page is a Japanese Yume Nikki fangame. The player starts as Akatsuki, a girl unable to leave her room. Her goal is to explore the dream world and collect all 13 effects. There is a notebook on the desk in Akatsuki''s dream room the player can interact with that shows sketches of all the effects the player collects throughout the game. Hanatsuki, the other player character, is unlocked after completing certain tasks in Akatsuki''s dreams.' FROM games WHERE igdb_id = 201304 ON CONFLICT (game_id, language_code) DO NOTHING;
