INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('international-snooker-challenges', 175857, '2013-05-02', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Snooker: Challenges', 'International Snooker returns with 108 bite sized challenges. Snack gaming at its very best! Using the critically acclaimed ‘2012’ engine, Challenges gives the player 108 bite sized mini-games. Everything from a single shot to historic moments in world snooker. Remember the 1985 ‘black ball’ final or Jimmy White coming so close to being world champion in 1994? Completing a challenge earns stars, 3 stars for a perfect result down to 1 star for a scrappy win. Collect enough stars per pack of challenges to win a bronze, silver or gold trophy in the prize room. With 108 challenges there’s hours of gameplay and lots of variety bringing a fresh, new and unique appeal to snooker games.' FROM games WHERE igdb_id = 175857 ON CONFLICT (game_id, language_code) DO NOTHING;
