INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('half-life-2-survivor--1', 320851, '2013-06-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zd8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half-Life 2: Survivor', 'The arcade version of Half Life 2 was released mainly in Japan on June 28, 2006. Survivor runs on the Taito''s Type X with a 32" attached monitor running at 1360x768. On June 18, 2013 the complete Half-life 2: Survivor 2.0 content dump was released, soon after that the game was modified to run on a regular Windows PC by Marphy Black, ben1066, and several other members of Facepunch Studios Forum. The port gives access to the developer console which was disabled in the original arcade version, therefore making multiplayer possible through the use of console commands. The game requires the screen resolution to be at least 1360x768, as the position of most of the user interface elements was optimized for the arcade machine''s resolution and cannot be changed.' FROM games WHERE igdb_id = 320851 ON CONFLICT (game_id, language_code) DO NOTHING;
