INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oil Drill', 'Drill and deliver oil through 10 challenging levels, both offshore and onshore. Experience different deliver missions for make a profit from your oil. Use your profits to unlock more challenging levels. Drill safely for the best outcome through layers of water, sand, stone and hardstone to get down to the oil without cracking your drill.' FROM games WHERE igdb_id = 22364 ON CONFLICT (game_id, language_code) DO NOTHING;
