INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aliens Like Milk', 'Alex is a cute alien. He likes milk very much, but what a pity – there is no more milk in the fridge! It''s time to go in search of cows who will treat Alex with milk. Go towards the new adventures... In this breathtaking physics puzzle you will use interesting mechanisms to rescue all good cows. Collect stars on your way, they will help you to unlock the new planets.' FROM games WHERE igdb_id = 200186 ON CONFLICT (game_id, language_code) DO NOTHING;
