INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maximus', 'Maximus brings you high tempo ARPG action, inspired by the golden hack ''n slash era of arcade gaming. An evil entity known as ''Mr.B'' threatens to take over the world. Four heroes set out for justice: Julius Maximus the swashbuckler, whose mum got stomped by Bruticus the dragon. Bishop the archer, whose twin brother Raven was killed. Alyssa the spellsword, whose house got burned just after she paid off the mortgage... and Frank the destroyer, who fell into a cauldron of magic potion when he was a boy to become a beefcake of a warrior.' FROM games WHERE igdb_id = 333766 ON CONFLICT (game_id, language_code) DO NOTHING;
