INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'History''s Ice Road Truckers', 'Do you have what it takes to conquer the world''s deadliest roads? Join Hugh, Lisa, and Alex in Ice Road Truckers the game as you battle the toughest winter roads the world has to offer. Tackle slippery terrain, avoid frozen lakes, and boost over ramps to see how many miles you can go before the ice road claims another victim.' FROM games WHERE igdb_id = 105530 ON CONFLICT (game_id, language_code) DO NOTHING;
