INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Legends of Chima Online', 'Explore the vast and dangerous World of CHIMA ruled by animal warriors in the brand new, free-to-play LEGO Legends of CHIMA Online game. Play co-operatively with friends or venture out as the solo hero in an action-packed multiplayer adventure game based on the highly popular toy line and cartoon series from the LEGO Group! Choose from the Lion, Eagle, Gorilla and Bear tribes and customize your very own warrior. Smash LEGO objects to collect studs, bricks and special items. Build and expand your Outpost to craft powerful weapons, armor, powers and gear to defeat the Croc, Raven, Rhino and Wolf tribes. Solve fun puzzles, complete challenging missions, and unleash the power of CHI in epic battles!' FROM games WHERE igdb_id = 233277 ON CONFLICT (game_id, language_code) DO NOTHING;
