INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeonfield', 'Plunked into a 2D, side-scrolling world randomly generated and populated with dangerous dungeons, and you''ll need to smash, stab, dig, and otherwise destroy your environment to gather the supplies you''ll need to craft and survive day-to-day. Turns out in a great battle, the kingdom was destroyed and all its people carted off to dungeons, and only you can save them.' FROM games WHERE igdb_id = 331961 ON CONFLICT (game_id, language_code) DO NOTHING;
