INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Muv-Luv Alternative: Total Eclipse', 'Muv-Luv Alternative: Total Eclipse is a side story in the Muv-Luv series of visual novels and takes place in the same universe as Muv-Luv Alternative. The story takes place at Alaska''s Yukon base, test site 18, where first-class staff from all over the world regardless of country gather to work on new Tactical Surface Fighters. The main characters are engineers and pilots and it features many TSFs that failed to show up in Alternative.' FROM games WHERE igdb_id = 11799 ON CONFLICT (game_id, language_code) DO NOTHING;
