INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('call-of-duty-ghosts-hardened-edition', 47493, '2013-11-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3b2d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/a4b3kagugavl17p0vurh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: Ghosts - Hardened Edition', 'Call of Duty: Ghosts Season Pass Get four epic DLC Map Packs, each delivering a collection of fresh Call of Duty: Ghosts multiplayer content and more. Plus, you''ll receive the Team Leader digital content pack, a Season Pass-bonus that includes a unique MP character head, headgear, weapon camo, reticle, player patch, player card and player background. Free Fall Dynamic Bonus Map A brand-new dynamic downloadable multiplayer map that drops you into a shattered skyscraper on the brink of collapse. Frantic action is thrown into overdrive as the skyscraper continues to fall throughout the match, evolving gameplay in real-time. Paracord Strap A modern day military staple, this wearable tool allows you to carry over 10 feet of versatile paracord on hand wherever you go. Collectible SteelBook Secure a limited edition steel game case featuring premium artwork. Player Patch Show your enemies what you stand for with an in-game Ghosts insignia player patch. Player Card Leave your mark on any killcam with an in-game Ghosts insignia player card. Player Background Stand out in any lobby list with a Ghosts-themed player background. Official Call of Duty Ghosts Soundtrack: Upgrade your playlist with a digital copy of the in-game score.' FROM games WHERE igdb_id = 47493 ON CONFLICT (game_id, language_code) DO NOTHING;
