INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat’s Catch', 'Keep the bird safe for as long as you can while a rogue housecat is trying to catch it! The longer you hold out, the more desperate the cat becomes. He’ll take extreme measures like throwing bombs, slashing with scythes and transforming into a wild tornado-frenzy! Increase your highscore, collect feathers and unlock new birds and themes! Do you think you have what it takes to keep the bird from becoming the Cat’s next Catch?' FROM games WHERE igdb_id = 327248 ON CONFLICT (game_id, language_code) DO NOTHING;
