INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Signal Ops', 'Signal Ops blends elements of a tactical shooter, stealth, strategy, and puzzle solving. Your squad can be customized each mission by selecting from six agents with unique abilities and equipment. Some agents are geared towards sneaky play, and others are more combat oriented. You''ll usually find yourself using a mix of both stealth and combat, and this can also vary depending on the mission.' FROM games WHERE igdb_id = 16734 ON CONFLICT (game_id, language_code) DO NOTHING;
