INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slenderman''s Shadow', 'Slenderman''s Shadow is a series of playable maps created (8th Oct 2012) by Marc Steene and Wray Burgess, and later (13th Jan 2013), as a full remake, a survival horror game, based on Slender: The Eight Pages by Parsec Productions. The series'' original website is no longer active. Marc Steene has since reuploaded the Unity remake, completely free, on a new itch.io page.' FROM games WHERE igdb_id = 63804 ON CONFLICT (game_id, language_code) DO NOTHING;
