INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('papas-cupcakeria', 210492, '2013-08-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7jzk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa''s Cupcakeria', 'Cook a ridiculous amount of delicious cupcakes for all your wacky customers in Papa''s Cupcakeria! Papa''s Cupcakeria just opened up in the picturesque town of Frostfield and you''ve been "hired" to run the restaurant all by yourself. You will need to master all 4 of the stations to become a cupcake crafting master. Take your customers quirky orders in the Order Station. Prep the pan with wrappers and gooey batter in the Batter Station. Cook the cupcakes to perfection in the Bake Station. Finally, frost the cupcakes and cover them with delicious decorations in the Build Station. As you level up and build a loyal customer fan base, you will notice the seasons changing all around you. Celebrate the 12 holidays with special clothing, furniture, and awesome seasonal toppings. With over 100 menu items, 90 achievements, tons of furniture, over 80 customers, and all the holidays you can imagine, this is by far the most epic restaurant Papa Louie has ever opened!' FROM games WHERE igdb_id = 210492 ON CONFLICT (game_id, language_code) DO NOTHING;
