INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.D. Spy', 'J.D. Spy (short for "John Doe Spy") is a puzzle-adventure game that pulls you, an innocent civilian, into the midst of an international terrorist plot. To save your own life, you will be required to hack into secured computer systems, decode encrypted messages, decipher computer algorithms, examine photographs for clues, and much, much more.' FROM games WHERE igdb_id = 230596 ON CONFLICT (game_id, language_code) DO NOTHING;
