INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anno 2070: Complete Edition', 'The complete edition of Anno 2070, containing both the main game and the Deep Ocean DLC, plus exclusive content: ANNO 2070 Deep Ocean The Development Package (Mini-Campaign) The Guardian Package (new buildings) Eden Line Package (Ornamental buildings & decorations) Central Statistical Package (new building skins) Crisis Response Package (2 new missions) Distrust Series Package (Ornamental buildings & decorations) Silent Running Package (New Submarine vehicle and skins) Ornamenals Nordamark (Buildings and skins) Paket E.V.E (UI overhaul) World Event “Free Eden” World Event „The Nordamark Conflict“ World Event “Global Distrust” Exclusive Premium Content: The complete Anno 2070 Soundtrack The updated Tree of Technologies poster' FROM games WHERE igdb_id = 52401 ON CONFLICT (game_id, language_code) DO NOTHING;
