INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riding Star', 'Ride like a world champion! Breathtaking action, challenges in show jumping, dressage and cross country riding are waiting for your talent. You train rides and horses and lead them to success. The world championship venue, the world''s biggest riding Stadium in Aachen, invites you to take part in the finals in the large show jumping stadium and the Deutsche Bank stadium where the dressage championships take place.' FROM games WHERE igdb_id = 17047 ON CONFLICT (game_id, language_code) DO NOTHING;
