INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'History Lesson', 'It’s the year 5279.  Humanity has, with the help of the technology left, slowly begun to rebuild their civilization.  By using historical documents and recordings stored on old computers they have created interactive text-simulators to reconcile with and learn from their past mistakes.' FROM games WHERE igdb_id = 139388 ON CONFLICT (game_id, language_code) DO NOTHING;
