INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blastron', 'Blastron is a free-to-play, turn-based action-arcade game developed by Exploding Barrel Games and launched by Kabam in 2013 for iOS and Android. Often compared to Worms, players control customizable robots in a wasteland, using explosive weaponry to destroy opponents in multiplayer battles. It features both online competitive modes and a single-player campaign.' FROM games WHERE igdb_id = 388732 ON CONFLICT (game_id, language_code) DO NOTHING;
