INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Chrono Adventure', 'Sonic Chrono Adventure is the last in LakeFeperd''s series of Sonic fangames made in Sonic Worlds, an engine built within Multimedia Fusion 2. It was developed at a time After The Sequel was feature-complete but also waiting for the sound team to finish composing their original soundtrack. Not wanting to exploit them, Lake went with existing songs for this final installment and released it in December 2013.' FROM games WHERE igdb_id = 19739 ON CONFLICT (game_id, language_code) DO NOTHING;
