INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fast-break-pro-basketball-3', 82314, '2013-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/u330lcww5zgbjmrac6ac.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/q4udmbd5tdjenfbhzjkg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fast Break Pro Basketball 3', 'Fast Break Pro Basketball 3 brings you the option to simulate the past, present, and future of professional basketball. The new historical database includes past players starting with the 1946 season. Draft classes can be fictional, historical, imported from Fast Break College Basketball or Fast Break College Basketball 2010, or imported from custom draft files. The game universe now has room for multiple active leagues at once. Advanced customization options allow for leagues with up to 40 teams as well as developmental leagues or tiered leagues with promotion between leagues. The simulation possibilities are endless.' FROM games WHERE igdb_id = 82314 ON CONFLICT (game_id, language_code) DO NOTHING;
