INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('titan--2', 159107, '2013-06-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gtp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxuk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titan', 'Titan is a HD remake of the 1988 game by Titus France. The great block breaker developed by Titus Interactive in 1988 is back with a brand-new HD version featuring superb 3D environments. Locked up in an 80-level tower by a mad scientist, use your brainpower to help you to escape. Armed with your pod (a cubic robot) and a metal ball, avoid the numerous traps and try to find the way out. Titan is an innovative block breaker in which you control a cube at the center of the screen that allows you to move a ball in all directions and destroy the bricks. In this game, it is not reflexes that count because you are inside an enclosed arena and the ball cannot get out. It is brainpower and strategy that will carry the day. In each arena, different surprises and riddles await you... you will have to try to understand how to get out and, above all, how to avoid the traps. Some bricks can be destroyed by the ball, others by your pod. Teleporters allow you to navigate from one zone to another, the ice makes you slide, while mortal robot-pods try to hunt you down and traps try to destroy you... This title was delisted from Steam on August 8, 2018' FROM games WHERE igdb_id = 159107 ON CONFLICT (game_id, language_code) DO NOTHING;
