INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Talking Ginger 2', 'Ginger''s Birthday - It’s time for some birthday fun! Talking Ginger, the cutest little kitten, is growing up and wants you to celebrate his birthday with him. Join him for the best party ever - with awesome food and loads of games! Yes, you’re invited to hang out with the most adorable kitten in the world!' FROM games WHERE igdb_id = 344922 ON CONFLICT (game_id, language_code) DO NOTHING;
