INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Benji Bananas', 'Benji Bananas is a free-to-play mobile game from Animoca Brands available for download on the App Store and Google Play. It is a popular action game (over 50 million downloads) in which players make Benji the monkey and his friends leap from vine to vine through the jungle. The transition of Benji Bananas to P2E begins with owning the Benji Bananas Membership Pass NFT. This NFT (ERC-1155) allows owners to earn Primate tokens by playing Benji Bananas; Primate tokens can be swapped for ApeCoin and other coins within the Animoca Brands ecosystem!' FROM games WHERE igdb_id = 234749 ON CONFLICT (game_id, language_code) DO NOTHING;
