INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB 2K13', 'MLB 2K13 delivers hours of baseball action for any level of sports fan or gamer. Master our signature right analog pitching controls to achieve perfection on the mound, enjoy the authentic baseball environment of MLB Today featuring real life commentary and statistics, and develop winning players and teams in My Player, Franchise & Postseason modes. Available March 5 for Xbox 360 and PlayStation 3. Visit facebook.com/MLB2K for more details.' FROM games WHERE igdb_id = 47409 ON CONFLICT (game_id, language_code) DO NOTHING;
