INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aj-jump-animal-jam-kangaroos', 88986, '2013-12-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/iolbdvyauxt6o3glldqg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kwewgwefvdizfjusyozu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AJ Jump: Animal Jam Kangaroos!', 'National Geographic Animal Jam leaps into your hands with AJ Jump!  Adopt one of these playful kangaroos and jump through canyons, cliffs and clouds -- all the way to the moon!  Dress your kangaroo in outrageous fashions and challenge your friends!  Learn about real kangaroos! The included AJ Academy e-book is full of fun kangaroo facts, photos and videos.  Earn Gems that you can spend customizing your kangaroo! If you have a free Animal Jam account, you can also send Gems to your animals in Jamaa!  Play AJ Jump to unlock the exclusive pet joey in Animal Jam -- your own baby kangaroo! This pet is available to ALL Jammers, even if you aren''t a Member.' FROM games WHERE igdb_id = 88986 ON CONFLICT (game_id, language_code) DO NOTHING;
