INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where''s My Mickey?', 'Where''s My Mickey is another part from the series Where''s My Water. Where''s My Mickey? introduces a whole new world of life-like physics-based gameplay with stimulating weather mechanics and humorous animations. Immerse yourself in the ultimate mobile gaming experience as you watch funny episodes while solving challenging puzzles! Tap, swipe, and swirl to help Mickey collect water and complete each story. Every drop counts!' FROM games WHERE igdb_id = 63275 ON CONFLICT (game_id, language_code) DO NOTHING;
