INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corpse Party D2: Depths of Despair', 'Corpse Party D2: Depths of Despair is an RPG Maker VX Ace game based on the original NEC PC-9801 version of CORPSE-PARTY featuring influences and designs from Corpse Party for the PlayStation Portable. The game was written by Jackkel Dragon and illustrated by Hiragi-HOUX, and was released on November 15, 2013. It is known under the abbreviation CPD2.' FROM games WHERE igdb_id = 170023 ON CONFLICT (game_id, language_code) DO NOTHING;
