INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paper Mario: Great Star Offensive', 'Paper Mario: Great Star Offensive is a Paper Mario styled fangame by SEVA, it is a full-length game based on the Nintendo 64 game. Great Star Offensive plays like any traditional Paper Mario game, fight Action Command-based battles, equip Badges, buy items, and so forth. The game features new locations along with old ones.' FROM games WHERE igdb_id = 338742 ON CONFLICT (game_id, language_code) DO NOTHING;
