INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Happy Mouse', 'Happy Mouse is a game loosely based on the creepypasta suicidemouse.avi Pathological emotional state characterized by exaggerated feelings of sadness, melancholy, depression, decrease of the self-esteem that don''t respond to a real cause that finishes in death in many cases. When you think something is right, beneath it lies something horrible, something dark...' FROM games WHERE igdb_id = 241373 ON CONFLICT (game_id, language_code) DO NOTHING;
