INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DragonBox Algebra 12+', 'Build a Greater Understanding of Algebra With more levels and more advanced equations Algebra 12+ moves beyond its critically acclaimed predecessor, Algebra 5+. More Levels & Harder Equations Algebra 5+ gave us the basics, now comes the hard part. In Algebra 12+ you deep dive into advanced algebraic concepts. Covered in the App: Addition, Division, Multiplication, Parentheses, Positive/Negative Signs, Addition of Fractions (Common Denominator), Collection of Like Terms, factorization, Substitution.' FROM games WHERE igdb_id = 276798 ON CONFLICT (game_id, language_code) DO NOTHING;
