INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('company-of-heroes-2-red-star-edition', 19461, '2013-06-25', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co39w9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tc5qmfhlo5qfib3rclmc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Company of Heroes 2: Red Star Edition', 'Command the Soviet Red Army in the world’s darkest hour as you battle to free Mother Russia from German enemy invaders. Your military tactics hold the power to tip the very balance of this brutal conflict. Engage in tactical combat that will define you as a military leader and wield the might of the Soviet Empire as you smash your way to Berlin. Red Star Edition includes: Steel Book Packaging: Exclusive steel book packaging. ‘Theatre of War’ Mini Pack*: Single Player/Co-op Mission set available post launch. Vehicle Skin Combo Pack: Unlock 24 historically-accurate new skins for the game’s multiplayer mode. Commanders Archetypes: 5 Multiplayer Commander Abilities for multiplayer customization including the unique Soviet Terror Tactics. Commander Pass: Unlock another 5 Multiplayer commanders post launch. Company of Heroes Complete Pack: The Award winning game collection that started it all. Includes the original Company of Heroes a well as its expansions Opposing Fronts & Tales of Valor. Exclusive Faceplate & integrated badge: Customize your in-game faceplate.' FROM games WHERE igdb_id = 19461 ON CONFLICT (game_id, language_code) DO NOTHING;
