INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Eclipse', 'The eclipse stars, a source of mythical powers, have been unleashed upon the world. As a result, the entire Mushroom Kingdom has been shrouded in the shadows of an everlasting eclipse. It is up to Mario to collect these stars, and save everyone from an eternal twilight.' FROM games WHERE igdb_id = 320228 ON CONFLICT (game_id, language_code) DO NOTHING;
