INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s African Adventures', 'Explore the vast wilderness of Africa on foot and by vehicle, where you’ll go head to head with the most ferocious beasts on the planet as you attempt to take down the biggest of the "Big 5": The Rhino, Lion, Leopard, Cape Buffalo & African Elephant! Cabela''s African Adventures features vast hunting areas 5x the size of any other Cabela''s console games, with challenging and fun boss animal fights. Enter and leave your vehicle anytime, anywhere while you take on large herds of stampeding buffalo, packs of predators, and dream prey across 5 different biomes!' FROM games WHERE igdb_id = 7807 ON CONFLICT (game_id, language_code) DO NOTHING;
