INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sushi Clickers', 'After the great success of Cookie Clickers, now on your iPhone, iPod and iPad has arrived.... Sushi Clickers! Be prepared for endless hours of fun and entertainment! The game is very simple: - Make as many maki as you can by clicking or tapping on a giant Onigiri as fast as you can. - As soon as you have enough maki take a trip to the shop and use your maki to buy upgrades to make maki even quicker!' FROM games WHERE igdb_id = 343971 ON CONFLICT (game_id, language_code) DO NOTHING;
