INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shep Hard', 'Keep your flock safe in this extreme shepherding game. Your goal is to raise 10 platinum sheep. You''ll need to grow your plot, smack away wolves, shear your sheep, and eventually lay down mortar towers and turrets to get it done in this insane blend of Tower Defense and King of the Hill.' FROM games WHERE igdb_id = 281439 ON CONFLICT (game_id, language_code) DO NOTHING;
