INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ben 10 Omniverse: The Return of Psyphon', 'In Ben 10 Omniverse: The Return of Psyphon players control Ben Tennyson as he battles against the villain Psyphon, using various alien transformations to defeat enemies and complete missions. The game offers action-based gameplay where players can switch between different alien forms to overcome challenges and progress through the storyline.' FROM games WHERE igdb_id = 344520 ON CONFLICT (game_id, language_code) DO NOTHING;
