INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atum', 128624, '2013-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x3o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7k65.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atum', 'ATUM pulls the player into a world where the player is the mechanic. It brings a novelty take on the point-and-click gameplay of previous generations and combines it with platformer puzzles. The game toys with the concept of multi-layer gameplay, dipping its layers in mathematical loops and philosophical recurrences.  The design and the aesthetics are influenced by a manifold of science fiction classics, Blade Runner and Philip K. Dick''s story Martian Time Slip among others.  The game environment, used as narrative device, provides a considerable amount of references and clues that complement the underlying storyline.' FROM games WHERE igdb_id = 128624 ON CONFLICT (game_id, language_code) DO NOTHING;
