INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('attouteki-yuugi-mugen-souls-z', 44589, '2013-05-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobo2j.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Attouteki Yuugi: Mugen Souls Z', 'Mugen Souls Z is Back with Tons of Features and Improvements: Mugen Souls Z aka Attouteki Yuugi: Mugen Souls Z is a Japanese RPG featuring a massive free-roaming battle map, exceptional turn-based combat, huge amounts of customization, a level cap of 9999, and billions of enemies’ damage points to quench even the most hardcore RPG fan’s thirst! Mugen Souls Z is developed by Compile Heart and co-produced by GCREST as the second installment in the Mugen Souls series with loads of added new features and improvements to the game! Journey to an Ultimate Adventure: Following the story of the first game, players take control of the new protagonist Syrma, who meets Chou-Chou before the end of the first game’s events. Travel across twelve nonsensical worlds of ridiculousness with your very own spaceship and unfold tricks and secrets abound on each world. Root for Syrma as she stops an ancient threat to her world that has recently awakened. Players also have the opportunity to create heroes of their own, they can dress them as they want and kill how they want. Deal damage in the hundreds of millions using “Damage Carnival” and take on tons of undisputed game systems! Engage in an ultimate adventure with a cast of overwhelming characters only in Mugen Souls Z!' FROM games WHERE igdb_id = 44589 ON CONFLICT (game_id, language_code) DO NOTHING;
