INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Franchise Hockey Manager 2013', 'Franchise Hockey Manager is a hockey sports management game. The player can take control of any team in 19 playable leagues, including NHL, AHL, KHL and many other European elite leagues, as well as North American minor and junior leagues. A team is led to success by managing every aspect of hockey team: roster management, contracts and player trades, coaching, scouting, finances. Furthermore, you can create your own custom league, fill it with your fictional teams and players, set the rules and play.' FROM games WHERE igdb_id = 63352 ON CONFLICT (game_id, language_code) DO NOTHING;
