INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('urakata-hakuoki', 60978, '2013-03-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xmz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjaes.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urakata Hakuoki', 'On a night in Kyoto, another story begins. A brother and sister who operates a dojo encounters a figure with an asagi-coloured haori; a suspicious shadow with white hair — a shinsegumi rasetsu! In order to avenge her elder brother who sacrificed himself to protect her, the sister takes up the sword. A determination that will see her through turbulent times. A time where she meets a group of men. This is the story of a girl gets embroiled in a turbulent era and the men who are building a new one.' FROM games WHERE igdb_id = 60978 ON CONFLICT (game_id, language_code) DO NOTHING;
