INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Fairies: Hidden Treasures', 'After discovering her talent, Tinker Bell invents, builds and repairs new contraptions to make life easier for her fairy friends. Your child can join Fairy Mary, Bobble and Clank, Rosetta, Iridessa and all the other fairies as they teach Tink about Pixie Dust, sprinting thistles, the many uses of acorns, and the magical world of Pixie Hollow. Each episode of this puzzle based adventure features mini stories from the world of Pixie Hollow and is a part of an even larger tale.' FROM games WHERE igdb_id = 63748 ON CONFLICT (game_id, language_code) DO NOTHING;
