INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('7-card-studs', 251263, '2013-08-10', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Card Studs', '7 Card Studs is a free solitaire and multiplayer strategic board game using poker hands. Challenge yourself or a friend to a free poker based board game! The board is 7x7 and has 49 squares. 13 cards start face down on the board and are not revealed until all the other cards are placed. The goal of the game is to make the best 5 card poker hands in each row and column. Every row and column has 7 cards, but only the best 5 will be used. When playing solitaire the player scores the points in both the rows and the columns. In multiplayer head to head mode, player 1 plays the rows and player 2 plays the columns in a head to head show down on the same board.' FROM games WHERE igdb_id = 251263 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 251263 AND ge.slug = 'card-and-board-game' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 251263 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
