INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('farming-giant', 10310, '2013-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zl8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wjgp44y8w1dpeoab1veb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farming Giant', 'In the best tradition of the giants-series the player will get a first-class business simulation crafted with a lot of details. The player will build farms, maintain and upgrade his properties. Whether farming or ranching, the experience covers all parts of agriculture. With the right strategy and the courage for expansion, international success is guaranteed. A huge game world, a variety of production processes and trade opportunities and various game modes as well as achievements provide long-lasting fun. Furthermore the agricultural giant impresses with wide range of management options (from seed to distribution - the players takes decisions by himself) and an extensive fleet of vehicles. A detailed skill tree provides RPG elements and offers the opportunity to specialize more and more!' FROM games WHERE igdb_id = 10310 ON CONFLICT (game_id, language_code) DO NOTHING;
