INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Blockheads', 'The Blockheads is a two-dimensional exploration, building, crafting, and survival sandbox game. It was created by David ''MajicDave'' Frampton, an indie developer and owner of Majic Jungle Software. The game is set in a procedurally-generated world, where in the player controls avatars called blockheads; that can destroy or create blocks, collect or craft material resources, or form exotic structures. There are also a variety of biomes, such as: equators, poles, oceans, mountain ranges, deserts, and vast underground cave networks using a wide range of resources.' FROM games WHERE igdb_id = 39213 ON CONFLICT (game_id, language_code) DO NOTHING;
