INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Youda Marina', 'Youda Marina brings together all the fun of landscape design with exciting time management action! Build the marina of your dreams and get some sun and fun each time you play. Be creative with your exotic harbor and have fun managing its everyday problems. As the harbor master you will be responsible for keeping all your Marina visitors happy and spending money. Create the most beautiful marina in the world!' FROM games WHERE igdb_id = 9305 ON CONFLICT (game_id, language_code) DO NOTHING;
