INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('imaginstruments', 18979, '2013-05-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60vg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ppzemvxfxgueixhrxhfi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imaginstruments', 'Set your creativity free! Become an Imaginstruments virtuoso and start making music with your PS Vita. Mix drums, melodies and bass sounds, add effects and change the key and tempo of your tracks, all in real-time and on-the-go. With six virtual instrument tracks to choose from, you can bring each sound into the mix and start creating some unique grooves. Once you’ve got your track locked down, switch to the bass channel and combine four bass sounds to give your tune some funk, then twist your basslines up with a selection of effects and filters. Music at your fingertips • Bring six instrument tracks into the mix: a kick drum, a snare drum, a hi-hat, a cymbal and two keyboard melodies. • Add bass sounds and twist them up with a range of effects. • Adjust the key and tempo to suit your musical style.' FROM games WHERE igdb_id = 18979 ON CONFLICT (game_id, language_code) DO NOTHING;
