INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moorhuhn: Tiger and Chicken', 'The Crazy Chicken first saw the light of day 14 years ago, and has been on lots of adventures since then. Now it''s back to face its biggest challenge yet: In Crazy Chicken: Tiger & Chicken, you play the hero in a fast-paced story filled with terrifying enemies and dramatic combat. As a Shaolin fighter, you must liberate your oppressed people and save the love of your life.' FROM games WHERE igdb_id = 17822 ON CONFLICT (game_id, language_code) DO NOTHING;
