INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Shogi', 'The game has a free battle mode that you can play right away, and a level up mode that allows you to play against computers with 4 levels of strength under various conditions, allowing you to improve your skills while having fun. It also has a game record storage function and a two-player match function, allowing you to enjoy playing games with friends using a single Nintendo 3DS.' FROM games WHERE igdb_id = 222026 ON CONFLICT (game_id, language_code) DO NOTHING;
