INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Gem Collector', 'Embark on an adventure as Nomi, the volunteer gem collector from the Earth Tribe. Run, jump, fight enemies, solve puzzles, and collect gems in over 21 levels. Enjoy the 2D platforming madness with a friend, as the entire game can be played with drop-in and drop-out Co-Op. Push your skills to the max with hundreds of collectables to find and instense situations to maneuver through. Any fan of tradional 2D Platformers will be right at home with this game, get ready, and start collecting!' FROM games WHERE igdb_id = 85435 ON CONFLICT (game_id, language_code) DO NOTHING;
