INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyouren no Utage', 'A boy wakes up in the dark, cold cell after seeing the death of his family. What is this place, why is he here? While he tries to find the way out of this place, he experiences pieces of memories, flashbacks to solve the mystery of his abduction as well as someone else past... Take the role of a boy, Takuma, and explore this eerie place, find missing pieces of memories to solve and escape while running away from insane creatures that lurks about the place...' FROM games WHERE igdb_id = 150561 ON CONFLICT (game_id, language_code) DO NOTHING;
