INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars Pinball 7', 'Set in a galaxy far, far away, Star Wars Pinball lets you interact with the most iconic characters, and relive the greatest moments of the Star Wars universe mixed with exciting pinball action! Star Wars Episode V: The Empire Strikes Back, Star Wars Episode VI: Return of the Jedi, Darth Vader, Starfighter Assault, Star Wars: The Clone Wars, and Boba Fett. Choose to support the Galactic Empire or the Rebel Alliance with your high scores as the Star Wars Pinball community fights for the Balance of the Force!' FROM games WHERE igdb_id = 380936 ON CONFLICT (game_id, language_code) DO NOTHING;
