INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nano Assault EX', 'Stop the deadly Nanostray virus from spreading and contaminating civilization in Nano Assault EX, a fast-paced action shooter set within a visually stunning cellular system that leaps off the screen in full 3D. Control your microscopic Nanite ship inside the dangerous virus to fight off infections, navigate through alien cell clusters, battle bosses, and ultimately analyze and destroy the virus'' core to save humanity. Nano Assault EX is based on the original Nano Assault retail game plus the all-new survivor mode, new online rankings, support for Circle Pad Pro, improved gameplay, updated graphics, etc.' FROM games WHERE igdb_id = 47647 ON CONFLICT (game_id, language_code) DO NOTHING;
