INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('z-day-shootout', 240007, '2013-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co67mt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scljwv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Z Day Shootout', 'Do you love old school shooters ? Z Day Shootout is just that! Lot of weapons, lot of zombies. Just search and destroy! It happend so fast! We didn''t see it coming! The Virus was Spreading So quickly!... Soon everyone got infected! Well, not everyone... There is still a few of us. Fighting. Surviving! I was chosen for this mission! Best survivor, best GUNMAN! It''s up to me to clean this Town of the Undead! So What are you waiting for ? Pick up Your GUN and DO the Dirty Work! Good Luck. You''re gonna need it!' FROM games WHERE igdb_id = 240007 ON CONFLICT (game_id, language_code) DO NOTHING;
