INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crysis-3-hunter-edition', 46635, '2013-02-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2onl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/igquzgy6wixtes9atdq1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crysis 3: Hunter Edition', 'You''ll be granted the lethal, cloaking friendly Predator Bow, a unique weapon skin for the bow, and the all-seeing Recon Arrow on day zero. You''ll start multiplayer at level 5, letting you evolve faster than your prey. You''ll get immediate access to the silent & deadly "Hunter" Nanosuit module, a powerful perk perfect for the included Predator Bow. Finally, you''ll be able to experience Crysis 3 and the original Crysis together at launch when you preorder -- but only for a limited time!' FROM games WHERE igdb_id = 46635 ON CONFLICT (game_id, language_code) DO NOTHING;
