INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Cat''s Night 2: Orazio goes to town', 'The game takes place a few months after the first A Cat''s Night.  Now Orazio lives in the city of Forlì with a nice family and other cats.  But the streets of Forlì are not safe for dogs and cats: a group of evil people kidnaps the animals and take them away on their white van.  The Feline Council decides to ask for help: they call the hero of the Emergenza Randagi shelter, Orazio!' FROM games WHERE igdb_id = 125204 ON CONFLICT (game_id, language_code) DO NOTHING;
