INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Draw Rider Plus', 'Can you get to the finish line safely and securely? Draw Rider is not an ordinary race, here you are waiting for insidious tests from many hardcore levels. Get gold medals, becoming the best racer on each track, to unlock new levels and new characters. Thanks to the level editor you can create new tracks and share them with other players. Participate in the race for a while, communicate and evaluate the tracks of other players, become a part of the Draw Rider community!' FROM games WHERE igdb_id = 175394 ON CONFLICT (game_id, language_code) DO NOTHING;
