INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blur-overdrive', 322545, '2013-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9276.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuhue.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blur Overdrive', 'Blur Overdrive is a racing game from the overhead perspective that, despite having different camera views and controls from the original Blur (PC, XBox 360, and Playstation 3), still offers up a similar experience of driving in lightning-fast races with all kinds of dirty tricks. You have more than twenty different vehicles to choose from, all of which you can personalize by changing colors and adding different upgrades. Of course, the majority of them need to be unlocked by winning competitions and saving up money from different races. Your objective during each race is to come in first, but that doesn''t necessarily mean that you have to be the fastest. To help things go your way, you can use up to eight different power-ups that allow you to activate shields, drop mines, launch lightning bolts, and much more. Blur Overdrive is a fun three-dimensional racing game that, in addition to boasting excellent graphics, has truly great gameplay. Its control system, which is often a problem in other Android racing games, is a true delight.' FROM games WHERE igdb_id = 322545 ON CONFLICT (game_id, language_code) DO NOTHING;
