INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('classic-snake', 86701, '2013-03-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/fne7kh5n9qoj2kicavkx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/z0ni8loqoesxxsca5b0t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Classic Snake', 'The classic game of Snake - eat the targets & grow, but don''t run into anything ! A great way to relax and tune-out from your day for a quick break.  Boards - Classic board where snake wraps-around, Walls, Broken Wall, Spiral, and more Speeds - From very Slow to nearly impossibly Fast  Backgrounds - Star field scrolling, white, black, wooden, and more Music - 8-Bit retro soundtrack Controls - Directional or "Steering" controls (choose from Settings) Full Screen support Share a screenshot of your finished game on Facebook or Twitter ! Handy keyboard shortcuts: P; Play  B: Change background K: Change sKin (how the snake looks) M: Menu X: Toggle Sound Spacebar : Pause Cursor keys to move snake (WASD keys can also be used) Pick number of targets in the game: ONE or 5 or even 10 ! (choose from settings) High scores are saved for each speed and board Multiple speeds - Many boards - Full Screen support - Easy controls -  Lovely graphics - Smooth play.......classic snake is the snake game for everyone.' FROM games WHERE igdb_id = 86701 ON CONFLICT (game_id, language_code) DO NOTHING;
