INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell: Blacklist - Upper Echelon Edition', 'The United States has a military presence in two-thirds of countries around the world, and some of them have had enough. A group of terrorists calling themselves The Engineers initiate a terror ultimatum called the Blacklist - a deadly countdown of escalating attacks on U.S. interests. The pper Echelon Edition features: - Steelbook containing - Map of the conflict zone - Upper Echelon operational suit - Upper Echelon goggles (Gold) - Bonus Mission' FROM games WHERE igdb_id = 76983 ON CONFLICT (game_id, language_code) DO NOTHING;
