INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-beach', 323068, '2013-06-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co92r5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scujlw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Beach', 'After "The Event" humanity lies in shambles. Lawless marauders terrorize the last remnants of civilization. The only remaining habitable areas are remote tropical islands. It is up to you and those like you to fight back the forces of chaos and help restore law and order to the world. Form a powerful alliance and start rebuilding civilization one island at a time! Build your base, rally your troops, and engage in combat with thousands of other players online! Battle Beach is an exciting combination of city building, tower defense, and fast-paced real time combat with other live opponents. Raise an unstoppable army of snipers, tanks, and mighty Exo-Suits. Forge an alliance with other players and rise through the ranks. Fend off the Marauder hordes and restore order to a world lost in chaos.' FROM games WHERE igdb_id = 323068 ON CONFLICT (game_id, language_code) DO NOTHING;
