INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('muramasa-rebirth-blessing-of-amitabha-collectors-edition', 89921, '2013-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5x0g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21xi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Muramasa Rebirth: Blessing of Amitabha Collector''s Edition', 'Aksys Games is pleased to announce the Muramasa Rebirth Blessing of Amitabha Collector’s Edition! This special limited run collector’s edition will set your PlayStationVita handheld entertainment system apart from everyone else’s! Fully immerse yourself in the visually stunning world of Muramasa Rebirth, a world where myth and legend collide in this action-packed RPG designed specifically for the PlayStationVita system! Muramasa Rebirth Blessing of Amitabha Edition Features: Taking a cue from Vanillaware, developers of Muramasa Rebirth, the Muramasa Rebirth Blessing of Amitabha Collector’s Edition gives your PlayStationVita system an immersive experience for any fan of the Muramasa series! Aksys Games has collaborated with one of the best console accessory makers in the world, HORI USA, Inc., to offer a truly unique edition. Muramasa Rebirth PlayStationVita system Face Cover by HORI USA, Inc. – Protect your PlayStationVita system with this beautifully crafted PlayStationVita system Face Cover made by HORI USA, Inc.! Sporting the Muramasa logo on the front, make it known to your friends and family that you own this very limited edition! Muramasa Rebirth PlayStationVita system Skin by HORI USA, Inc.– Totally immerse yourself in the captivating world of Muramasa Rebirth with an exclusive PlayStationVita system Skin that completely protects the front panel of your PlayStationVita system! Using one of the many vibrant scenes from Muramasa Rebirth, this exclusive skin not only offers protection but beauty! Muramasa Rebirth PlayStationVita system Pouch – Complete your immersion with a black drawstring velvet pouch that easily puts your PlayStationVita system in your hands. High Res Framed Lithograph by Vanillaware – Specially made by Vanillaware, this new piece of art for this limited edition is truly one-of-a-kind reproduction For more information about Murasama Rebirth Blessing of Amitabha Collector’s Edition, visit . Muramasa Rebirth begins shipping June 25, 2013. Muramasa Rebirth Pre-Order Bonus: Pre-Order Muramasa Rebirth at Amazon or GameStop and receive an exclusive Muramasa Rebirth Abridged Soundtrack! Boasting numerous songs from Muramasa Rebirth, this pre-order bonus is a sure collector’s item for any Muramasa fan! Written by famed gaming and anime composer, Hitoshi Sakimoto of Basiscape, the Muramasa Rebirth Abridged Soundtrack features five songs that bring the colors and art of Muramasa to life.' FROM games WHERE igdb_id = 89921 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 89921 AND p.igdb_id = 46 ON CONFLICT DO NOTHING;
