INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Divinity: Dragon Commander - Imperial Edition', 'More than ''just another'' strategy game, Dragon Commander seamlessly blends turn-based and real-time strategy, action gameplay and roleplaying into a grand adventure. Plot the political course of your empire, move your armies into key locations in the world, command troops on the battlefield, and decimate the opposition as a ferocious dragon. Imperial Edition includes: - Digital soundtrack - Golden Dragon skin - Dragons on Earth campaign map - Behind the Scenes documentary' FROM games WHERE igdb_id = 51751 ON CONFLICT (game_id, language_code) DO NOTHING;
