INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love and War: Act I', 'Love and War: Act I (The Ties That Bind) is a fantasy RPG set in the world of Terra, an Alternate Reality Earth which has been ravaged by war for centuries. However, this turmoil is far away from Ryan Eramond, a young man recently graduated with the rest of his life in front of him... The story begins light-heartedly exploring the joys and trials of adolescence, though as our hero and his friends leave their small town they are thrust into the political unrest and unfamiliar dangers of the wider world.' FROM games WHERE igdb_id = 122860 ON CONFLICT (game_id, language_code) DO NOTHING;
