INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puyo Puyo!! Quest', 'Puyo Puyo!! Quest, not to be confused with Puyo Puyo!! Quest Arcade or Puyo Puyo Quest (the RPG-styled quest mode in Puyo Puyo Box), is a Puzzle RPG spin off of the Puyo Puyo series. The game features puzzle elements that is never before seen in the franchise, and uses a card system similar to other mobile RPG such as Puzzle & Dragons. The game is also renowned for reviving many older characters from across the franchise, and introducing many new original characters.' FROM games WHERE igdb_id = 80188 ON CONFLICT (game_id, language_code) DO NOTHING;
