INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('train-simulator-2014', 5545, '2013-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hk0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aqkjbccptnazinbucjvi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Train Simulator 2014', 'Train Simulator 2014 delivers everything you love about trains with the exhilaration of speed, stunning graphics, a variety of trains, real-world routes and challenging assignments. Whether you love driving trains, creating new routes or just watching the landscape fly by, your journey starts with TS2014. TS2014 includes three stunning routes for you to enjoy. Experience the super-modern London-Faversham High Speed route, featuring the stunning London St Pancras Station and sleek, streamlined Southeastern Class 395; alternatively, take charge of a Dash 9 at the head of a heavy freight train across the mountainous Donner Pass or the streamlined ICE 2 through beautiful German countryside from Hamburg to Hanover. Drive: Embark on a fun and rewarding career as a train driver. Explore: Drive a wide variety of trains on iconic routes around the world. Create: Easily build and share fantastic routes, and download more created by other players. Collect: Build your dream collection with a host of additional routes and trains.' FROM games WHERE igdb_id = 5545 ON CONFLICT (game_id, language_code) DO NOTHING;
