INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('doctor-who-say-what-you-see', 301934, '2013-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co88e2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsafu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doctor Who: Say What You See', 'Celebrate Doctor Who’s 50th Anniversary with Doctor Who: Say What You See! We all know that the only thing cooler than bow ties are Doctor Who cryptic picture puzzles, and we’ve created over 150 of them for our brand new game! Companions, gadgets, episode titles and monsters – all of these are hidden in our cunning paintings. Are you a big enough Doctor Who fan to solve them all? Doctor Who: Say What You See features three paintings with 50 Catchphrase-style cryptic puzzles on each – TARDIS Interior – Travel into the depths of the TARDIS, and discover the secrets within… Totter’s Lane – Go to the mysterious alleyway where it all began 50 years ago, when a strange old man and his granddaughter first appeared on Earth… Gallifrey (Coming Christmas 13) – Take a trip to the home planet of the Time Lords, and discover its secrets… Suitable for Doctor Who fans young and old, these puzzles cover the entire 50 year span of the show, and every correct answer is rewarded with a factfile revealing secrets and trivia about your favourite characters, gadgets and monsters. And if you get stuck, you can always use the ‘Stuck’ button to discover a few answers to get you started, or wave your Sonic Screwdriver to reveal the hidden hint coins on each painting. So what are you waiting for? It’s time to save the universe from a puzzling fate, and only YOU can do it! Alons-y!' FROM games WHERE igdb_id = 301934 ON CONFLICT (game_id, language_code) DO NOTHING;
