INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garfield''s Wild Ride', 'In Garfield’s dreams, he can fly! Just touch the screen to take off and release to descend. Avoid obstacles and enemies to clear the various levels. On your way, collect coins and lasagna to help Garfield. With those, you will be able customize Garfield with fun accessories and add power-ups. Dive into this colorful cartoon world that everybody can enjoy!' FROM games WHERE igdb_id = 25163 ON CONFLICT (game_id, language_code) DO NOTHING;
