INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Story 2', 'Farm Story 2 is a vibrant 3D farm simulation game offering an immersive social experience in which players plant crops, raise animals, and engage in a variety of mini‑games and crafting activities. Set in a friendly, living world, you can decorate your ranch, adopt pets, fish, mine, cook meals, and socialize with neighbors to grow your farm into a true legend.' FROM games WHERE igdb_id = 359220 ON CONFLICT (game_id, language_code) DO NOTHING;
