INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-angry-video-game-nerd-game-over-2', 186376, '2013-08-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bk0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf4nr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Angry Video Game Nerd: Game Over 2', 'This is an old game of mine that I felt like sharing here. Problems may occur while playing it, so apologies up front. Original release date was back in 2010. Lord Gavin, a dark master with a once terrifying power to alter reality as he saw fit, sot to rewrite the physical world in his image, leaving those helpless to beg under his will. Thought time, he was cast into eternal imprisonment within the virtual world by heros chosen by fate and chance. There he would reside and spare the world from his dark intent. With the knowledge of him gone from the passing of time, Lord Gavin once agai became unbound from his virtual domain and was free to unleash his wrath into our world. With humanity staring Virtual Armageddon in the eyes, another chosen hero stood to face against this evil and drive it out of our world. That hero was known as "The Angry Video Game Nerd".' FROM games WHERE igdb_id = 186376 ON CONFLICT (game_id, language_code) DO NOTHING;
