INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyroclysm', 'You have RAGE QUIT at Super Meat Boy, pulled your hair out at The Binding of Isaac. Prepare to get your ass handed to you by the insane challenge that is Pyroclysm. This game is HARD! This game is addicting, I dare you to try and survive. Defend civilizations from the onslaught of a massive meteor field traveling through the galaxy. Travel to different locations, buy and upgrade your weapons, missiles, drones and bombs.' FROM games WHERE igdb_id = 54271 ON CONFLICT (game_id, language_code) DO NOTHING;
