INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-last-of-us-joel-edition', 102081, '2013-06-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ubw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last of Us: Joel Edition', 'Twenty years after a mutated fungus started turning people all over the world into deadly zombies, humans become an endangered species. Joel, a Texan in his forties with the "emotional range of a teaspoon" (to quote Hermione from Harry Potter), finds himself responsible with the safety of a fourteen year old girl named Ellie whom he must smuggle to a militia group called the Fireflies. And as if the infected aren''t enough of a hassle, they also have to deal with the authorities who wouldn''t let them leave the quarantine zone, as well as other survivors capable of killing anyone who might have something useful in their backpacks.' FROM games WHERE igdb_id = 102081 ON CONFLICT (game_id, language_code) DO NOTHING;
