INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('death-match-love-comedy', 136702, '2013-04-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co955h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxyh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Match Love Comedy!', 'Death Match Love Comedy, does the exact opposite of usual visual novel, as having a girl fall in love with you could mean your death. Basically, the premise of the game is that the player is a guy that just got transferred to a new school, and if a girl confesses her love to him, he explodes… and dies. To make matters worse, he falls into some sort of love triangle with two beautiful girls, leaving his fate up in the air. Unlike other dating simulations, where your goal is to get girls to fall in love with you, in Death Match Love Comedy, you’ll be doing everything you can to avoid just that, as you try to figure out the reason behind the love-fueled explosions. Additionally, there will be another mysterious phenomenon, such as angels, a friend who has some sort of prediction, weird dreams and whispers, and a strange pink cat-like creature.' FROM games WHERE igdb_id = 136702 ON CONFLICT (game_id, language_code) DO NOTHING;
