INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wonderbook: Book of Potions', 'Book of Potions (or Wonderbook: Book of Potions) is a 2013 augmented reality video game developed by SCE London Studio in conjunction with J. K. Rowling as a companion to the Harry Potter series and as a followup to the Wonderbook''s debut title, Book of Spells. It was released in Europe on 15 November 2013 and North America on 12 November 2013, alongside Diggs Nightcrawler and Walking with Dinosaurs.' FROM games WHERE igdb_id = 25099 ON CONFLICT (game_id, language_code) DO NOTHING;
