INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Pirate Warriors 2 - Collector''s Editon', 'One Piece: Pirate Warriors 2 is the breathtaking sequel of One Piece: Pirate Warriors, a big action/adventure game in which you will take down hordes of Pirates in the beloved world of One Piece. Immerse yourself by playing the “New World”, with your favorite’s characters and their latest techniques and costumes! The collector''s version contains a Luffy figurine made by the renowned Japanese sculptor Keiji Iwakura' FROM games WHERE igdb_id = 225688 ON CONFLICT (game_id, language_code) DO NOTHING;
