INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mexican Train Dominoes Gold', 'Whether you’re a newbie or a well-seasoned pro, get stuck in wherever you feel comfortable with our easy, medium, or hard difficulty settings. Got five minutes? How about five hours? Settle down for a minute or a marathon with our short, middling, or long game choices. If you’re new to dominoes our handy, easy-to-follow tutorial will help you get playing in no time. Simple controls and immersive audio-visual themes will have you hooked from the start. Both animated and simple backgrounds add to a pleasing ambiance for a truly exciting play environment.' FROM games WHERE igdb_id = 147732 ON CONFLICT (game_id, language_code) DO NOTHING;
