INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamscapes: The Sandman', 'Dreamscapes: The Sandman is a hidden object puzzle adventure where players enter the subconscious of a coma patient named Laura. Using a specialized device to navigate her fractured dreams, the objective is to solve environmental puzzles and defeat the Sandman, an entity trapping her within her own mind. Gameplay involves point-and-click exploration across various dream worlds, featuring logic-based mini-games and hidden object scenes. The experience focuses on collecting items to overcome character-driven fears, utilizing a progressive hint system to guide players through the narrative.' FROM games WHERE igdb_id = 10246 ON CONFLICT (game_id, language_code) DO NOTHING;
