INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moshling Rescue!', 'Moshling Rescue! is a match-three style application. The puzzle game is free to play but does include in-game purchases as assets that make levels easier to pass are all to be paid with real money. The game is designed for those over 13 years old, usually marketing itself as being made for the parents of the children who play Moshi Monsters.' FROM games WHERE igdb_id = 395487 ON CONFLICT (game_id, language_code) DO NOTHING;
