INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sono Hanabira ni Kuchizuke wo: Tenshi-tachi no Harukoi', 'Sono Hanabira ni Kuchizuke o: Tenshi-tachi no Harukoi is an adult visual novel and the fourteenth game in the Sono Hanabira ni Kuchizuke o series of games. It is the second of three visual novels in the "Angel" series and features the couple of Katakura Yuno and Ishigami Satsuki, who were introduced as supporting characters in Sono Hanabira ni Kuchizuke o: Tenshi no Akogare.' FROM games WHERE igdb_id = 12272 ON CONFLICT (game_id, language_code) DO NOTHING;
