INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragons-lair-ii-time-warp--2', 323845, '2013-05-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93mc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar37hj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Lair II: Time Warp', 'Dragon''s Lair II: Time Warp, the followup to Don Bluth''s arcade classic Dragon''s Lair, can now be enjoyed on your PC. This fully arcade authentic version includes all of the original scenes you''ve come to enjoy, and even the unreleased Director''s Cut ending not seen in the arcades. Other bonuses include a full watch feature to sit back and enjoy Don Bluth''s stunning animation. Princess Daphne has been spirited away to a wrinkle in time by the Evil Wizard Mordroc who plans to force her into marriage. Only you, Dirk the Daring, can save her. Transported by a bumbling old time machine, you begin the rescue mission. But you must hurry, for once the Casket of Doom has opened, Mordroc will place the Death Ring upon Daphne''s finger in marriage and she will be lost forever in the Time Warp! Bonuses Include: Full Watch Game Deleted Scene - Pirate Ship Animatic' FROM games WHERE igdb_id = 323845 ON CONFLICT (game_id, language_code) DO NOTHING;
