INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gunship-iii', 88489, '2013-06-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98ob.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuz7z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunship III', 'Immerse yourself into the mist of the Vietnam war as an US helicopter or a fighter pilot. Not like other flight sim games for mobile devices, in Gunship-III the cockpit is highly simulated with ultra-realistic 3D cockpit, full function dashboard, realistic sound effects and all moving parts. Graphics are highly detail with cities, jungles, airbases, also includes a vast terrain covers Vietnam, Laos and Thailand. In Gunship-III, you have more aircrafts available to fly more than any other games. We''re working hard to bring even more in future updates. Weapon systems in Gunship-III are also highly detail and accurate with real recorded sounds, high fire rate for miniguns as well explosion effect for bombs and rockets. Each mission features many AI aircrafts, you also have AI gunners onboard who will shoot at anything firing at them and make sure nothing could touch your aircraft. The enemy is also aggressive and fearless, they only shoot at you when in close range and be aware of those RPG, they sure take an aircraft down just by one hit.' FROM games WHERE igdb_id = 88489 ON CONFLICT (game_id, language_code) DO NOTHING;
