INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Max 4: Moonlight Diva', 'Metal Max 4: Gekkō no Diva (メタルマックス4 月光のディーヴァ Metaru Makkusu Fō Gekkō no Dīva, lit. "Metal Max 4: Diva of the Moonlight") is a the eight entry in the Metal Max series (besides Metal Saga series). It is a Japanese open world, nonlinear, vehicle combat role-playing video game published by Kadokawa Games for Nintendo 3DS on 7 November 2013. The game was developed by Cattle Call and 24 Frame. Animation produced by Studio 4°C. Famitsu awarded game a 35/40.' FROM games WHERE igdb_id = 63165 ON CONFLICT (game_id, language_code) DO NOTHING;
