INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Grid Run', 'Super Grid Run is a fast-paced simple to pick-up but hard to put-down multi-platform retro action game where you must avoid everything coming at you for as long as you can whilst the speed relentlessly increases testing your twitch-gaming skills to the limit!  Features  3 Difficulty Levels from Easy to Insane!  Global Cross-platform High Scores  Amazing Chiptune Music  from the talented Garry Lee!  New Future Game Modes Coming Soon!' FROM games WHERE igdb_id = 58638 ON CONFLICT (game_id, language_code) DO NOTHING;
