INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Tiny Death Star', 'Star Wars: Tiny Death Star was a business simulation video game developed by Disney Mobile and NimbleBit, and published by LucasArts for Android, iOS, Windows Phone, and Windows 8/RT devices. It is based on NimbleBit''s previous game, Tiny Tower, and is set in the Star Wars universe. In October 2014, less than a year after its launch, the game was removed from the Apple and Google stores by Disney "to focus on priority titles like Star Wars: Commander." Developer NimbleBit had not been informed by Disney prior to the removal.' FROM games WHERE igdb_id = 39245 ON CONFLICT (game_id, language_code) DO NOTHING;
