INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eggnogg-plus', 50288, '2013-10-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3u2s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16mt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eggnogg+', 'EGGNOGG+, a competitive arcade game of immortals sword-fighting to the death. Stab each other, hurl and ricochet your swords off of the walls and ceilings, engage in pugilism, jump over spike pits to make it past your eternal foe and reach the far end of the strange complex. Hurl yourself triumphantly, and finally, into the EGGNOGG. Includes procedurally generated bytebeat tunes that you can edit live, and also create additional songs.' FROM games WHERE igdb_id = 50288 ON CONFLICT (game_id, language_code) DO NOTHING;
