INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Our Two Bedroom Story', 'You work for a publishing house and decide to start living on your own. But a coworker’s in your new home?! “This is my house… but you could live with me.” When your new roommate hands you the key, your secret life together begins… Includes "Main Stories" in the App "Love 365: Find Your Story". Collection of Main Stories spanning the series up until the Proposal Epilogue for Minato Okouchi, Kaoru Kirishima, Shusei Hayakawa, Chiaki Yuasa, and Akiyoshi Zaizen.' FROM games WHERE igdb_id = 134016 ON CONFLICT (game_id, language_code) DO NOTHING;
