INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ski-region-simulator', 36429, '2013-01-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86jl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cgdtymcxaefbkso1xjjp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Region Simulator', 'The "Ski Region Simulator Gold Edition" contains plenty of features and possibilities: In the career mode you enter a unique and large winter landscape and experience the workaday life in the swiss alps in a completely adapted and freely accessible world. Through several activities you build up financial resources allowing you to buy better equipment. Thanks to the cooperation and official license of Kässbohrer you take control of authentic Pistenbully snow groomers. If the variety of machinery does not meet your needs, you can download plenty of vehicles, equipment and other modifications from the Internet. Because of the improved mod system you are able to install the new content easily and automatically.Key Features:Career mode with large economic system Official license of Pistenbully and many other vehicles Lots of missions, events and extensions guarantee long-term entertainment Multiplayer mode for playing together with friends over Internet/LAN Day and night cycle with weather changes Download of additional machines and maps with automatic mod installation Includes Mod SDK (contains Editor, Exporters and Sample Mods) Gamepad and steering wheel support The Gold Edition also includes the DLC1 and DLC2, containing even more tools and vehicles' FROM games WHERE igdb_id = 36429 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 36429 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
