INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen OG: Infinite Battle', 'This entry for the famed tactical strategy RPG is breaking away from it''s usual fare; Super Robot Taisen OG Infinite Battle is a third person shooting game! Infinite Battle is the exciting side story companion to Super Robot Taisen OG Saga: Masou Kishin III - Pride of Justice. Expect a brand new instance of alternate universe mech-on-mech tactical crossover battles with action oriented gameplay!' FROM games WHERE igdb_id = 214614 ON CONFLICT (game_id, language_code) DO NOTHING;
