INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Net Mahjong MJ', 'A home version of Sega''s MJ series of arcade mahjong games for PC and mobile devices, released in 2013 in Japan. Notable features include a gacha system for acquiring new characters, music, etc. and match commentary. It was later translated and released in North America for mobile devices in 2020, although this version had its online service shut down less than a year later.' FROM games WHERE igdb_id = 130811 ON CONFLICT (game_id, language_code) DO NOTHING;
