INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnage Racing', 'Strap in, gun your engine, and go full throttle into a turbocharged, hi-octane combat racing game. Carnage Racing combines seat-of-the-pants driving, tricks and stunts with explosive vehicle combat in a no-holds-barred race for the checkered flag. Take on the rest of the world with Carnage Racing''s exhilarating 8-way real-time multiplayer mode and show them who really rules the road. Carnage Racing is a high-stakes game with one aim - take out your opponents, earn cash and buy upgrades that''ll power you to global victory. Get ready for the race of your life.' FROM games WHERE igdb_id = 10073 ON CONFLICT (game_id, language_code) DO NOTHING;
