INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimpleRockets', 'Design your own rocket ships. Blast off into space. Explore the solar system. See if you have what it takes to be a rocket scientist. Choose and connect parts together to build rocket ships. You can fly through the intense atmosphere of Venus, or you can take advantage of the low gravity of Mercury. Whip around the sun and launch yourself out to the far reaches of the solar system.' FROM games WHERE igdb_id = 197672 ON CONFLICT (game_id, language_code) DO NOTHING;
