INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('postmortem-one-must-die-extended-cut', 30257, '2013-12-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86fz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vbrukt8zqzqbvdxxcsnm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Postmortem: One Must Die (Extended Cut)', 'Narrative-adventure playing an Agent of Death who must take ONE life that could change the fate of a conflict-torn Nation! Think The Walking Dead meets Home and The Last Express, with a dash of To The Moon! Freeform exploration with Rich dialogue What might you learn searching the fundraising Gala and talking to patrons? Perhaps the less you know the better? Meaningful choices and Unintended Consequences Can your choice change the fate of a Nation? What other result could your meddling have? Cast of ambitious and influential characters What if they die? More importantly... what if they live? Complex setting of violent domestic conflict and industrial revolution A devastated country - but is it your place to fix it? What if your educated guess is wrong? Dynamic and surprising Ending The choice is *entirely* up to you - but what other factors may be affecting the outcome? Online Stats to compare Your Choices with Anonymous aggregate stats of everyone''s playthroughs will let you see how your own choices compare! Are you one of the good guys?Free VersionThe basic game, without the extra character and bonus materials, is also available for free from our Official Website!' FROM games WHERE igdb_id = 30257 ON CONFLICT (game_id, language_code) DO NOTHING;
