INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Draw Rider', 'Draw Rider - a classic racing game, made in 2D. Your goal is to get to the finish line within a certain time. In the game you will find a huge variety of levels, the passage of which will open various options for character customization. In the beginning, there will be nothing difficult, but as soon as the training finished, will be a real hardcore!' FROM games WHERE igdb_id = 33349 ON CONFLICT (game_id, language_code) DO NOTHING;
