INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy Tactics S', 'Final Fantasy Tactics S was a mobile social game that featured more than 30 playable jobs from the Final Fantasy Tactics series, also including newer jobs such as Air Samurai and Musician. Gameplay involved joining a clan, engaging in quests and battling it out with other clans in daily tournaments.' FROM games WHERE igdb_id = 63312 ON CONFLICT (game_id, language_code) DO NOTHING;
