INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic: After the Sequel', 'Sonic: After the Sequel (abbreviated Sonic ATS), is a fan game created by LakeFeperd that is meant to explain the events that may have taken place between Sonic the Hedgehog 2 and Sonic 3 and Knuckles. In it, the player plays as Sonic and Tails, racing through numerous zones as Sonic and Tails go out to stop Dr. Eggman from crashing the Death Egg into (and attacking), the new, mysterious island known as Angel Island. It is the sequel to Sonic Before the Sequel.' FROM games WHERE igdb_id = 19722 ON CONFLICT (game_id, language_code) DO NOTHING;
