INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear Rising: Revengeance - Ultimate Edition', 'Metal Gear Rising: Revengeance is an installment in the Metal Gear series and set four years after the events of Metal Gear Solid 4: Guns of the Patriots. The items included in this "Ultimate Edition" are: - METAL GEAR RISING: Revengeance (Full game) - 8 MGR Downloadable Content Items - VR Missions - Jetstream Mission(Side-Story) - Blade Wolf Mission(Side-Story) - Cyborg Ninja Armor Skin(w/ powerful “Fox Blade”) - METAL GEAR SOLID 4: Raiden Skin - Commando Armor Skin - White Armor Skin(Healing Power Increase) - Inferno Armor Skin(Max Throwing Weapons Increase)' FROM games WHERE igdb_id = 99949 ON CONFLICT (game_id, language_code) DO NOTHING;
