INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CastleMine', 'Defend your castle from the evils that lurk below in this unique strategy game! You will need to dig deep into the earth to uncover treasures and destroy the enemies threatening your castle. Your foes will follow the path you dig so you must decide… Will you dig long and winding paths to slow your enemies down? Will you dig in search of treasure to help improve your defenses? Or will you dig up the cursed skulls that increase the power of your enemies but grant you greater rewards? These are the decisions you must make as both you and your castle grow in power!' FROM games WHERE igdb_id = 24548 ON CONFLICT (game_id, language_code) DO NOTHING;
