INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pizza Boy', 'A thief has stolen the pizza present! Oh no! You are forced to chase it through levels filled with threats and dangers but to your advantage you can throw bottles of soda. Watch out for evil birds and furious dogs while you collect pizza slices and strawberries in a yummy mix. And don’t forget to keep an eye out for lost kittens on your way ahead. In miraculous surroundings Pizza Boy is a true retro game sensation. Hurry and get it back before it runs cold!' FROM games WHERE igdb_id = 303746 ON CONFLICT (game_id, language_code) DO NOTHING;
