INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WolfPlay', 'Embrace pack life as you assemble your pack, breed your wolves, hunt for food, gain and protect your territory. Battle other wolf packs and NPC creatures as you explore your world. Develop your wolves into unique individuals and roleplay them with other members. The way you build your wolves'' characters influence how they interact with the immersive world around them!' FROM games WHERE igdb_id = 144817 ON CONFLICT (game_id, language_code) DO NOTHING;
