INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forever Quester', 'Forever Quester is your quest companion, playing the rpg that you just don''t have the time to play while you''re living your own life. When you turn your phone on and check the game, your hero will update you on what you''ve missed. Help him choose weapons, armors, mounts and professions, and check back often to see how he is progressing! Guide him as he seeks out the evil Xaxoor on a quest that could very well go on forever!' FROM games WHERE igdb_id = 243957 ON CONFLICT (game_id, language_code) DO NOTHING;
