INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ten by Eight', 'Action Button Entertainment presents: Ten By Eight - a puzzle game so smart, you will need to buy a new hat shortly after you finish your first round. Create long chains of matching tiles across the playing area, destroy rocks before they touch the ground, and don''t forget that two times three sometimes equals eight.' FROM games WHERE igdb_id = 63072 ON CONFLICT (game_id, language_code) DO NOTHING;
