INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7th Dragon 2020-II', '7th Dragon 2020-II is a Japanese role-playing game and the sequel to 7th Dragon 2020. Set a year after the events of the first game, Murakumo has moved its main base from the Metropolitan Government Building and is focusing on rebuilding. Squad 13 is called to the Tokyo Sky Tower to rid of some monsters to help the rebuilding process in the tower. However, a portal appears at the top of the Sky Tower and Dragons appear once more to strike down humanity.' FROM games WHERE igdb_id = 11826 ON CONFLICT (game_id, language_code) DO NOTHING;
