INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Train Simulator: The Holiday Express', 'All Aboard the Holiday Express! ''Twas the night before Christmas, when all through the house, not a creature was stirring, not even a mouse. The stockings were hung by the chimney with care. A train shot by as fast as a hare! Get yourself the Richie Rails ''Electric'' Holiday Express.' FROM games WHERE igdb_id = 53745 ON CONFLICT (game_id, language_code) DO NOTHING;
