INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medieval Merchants - A historical trading simulation', 'Discover the Hanseatic League of the 14th century and fight for gold and prestige - transition-free on your iPad and your Mac. Take on the role of a medieval merchant and allow the City of Lübeck to rise from a little fishing village to the most important trading center of Northern Europe. Build ships, sail the Baltic and the North Sea and compete for valuable trade goods throughout the Hanseatic League. Invest money and resources in the City of Lübeck and become its mayor - but only if your competitors aren‘t faster.' FROM games WHERE igdb_id = 95298 ON CONFLICT (game_id, language_code) DO NOTHING;
