INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The House of the Dead: Overkill - The Lost Reels', 'The House of the Dead: Overkill – The Lost Reels was released for iOS and Android. The game is split into three chapters, with the first two included and the latter third requiring an additional fee. Money can also be spent in exchange for coins that can unlock better weapons, including some based on other Sega games such as Vectorman.' FROM games WHERE igdb_id = 134305 ON CONFLICT (game_id, language_code) DO NOTHING;
