INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shiver: Moonlit Grove - Collector’s Edition', 'Shiver: Moonlit Grove – Collector’s Edition is a premium release of the third installment in the Shiver hidden object adventure series. Developed and published by Artogon Games and Big Fish Games, this edition expands the original game with exclusive content including a bonus chapter, replayable puzzles, and downloadable extras. You play as a young doctor sent to replace your missing foster father, only to uncover dark secrets in a mysterious village.' FROM games WHERE igdb_id = 214226 ON CONFLICT (game_id, language_code) DO NOTHING;
