INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reader Rabbit Kart Racing', 'Reader Rabbit Kart Racing is a character-driven racing game featuring familiar faces from the Reader Rabbit edutainment series. Players can choose from four characters: Reader Rabbit, Sam the Lion, Matilda the Mouse, and Charlie the Chipmunk; each with their own kart, and race across 12 vibrant tracks, including six reversed variants. The racetracks span cheerful environments like forests and hillsides, designed to evoke a playful atmosphere. Gameplay options include Time Attack, Single Race, and Tournament modes. As players race, they can collect alphabet letters scattered along the tracks to unlock surprises from Reader Rabbit.' FROM games WHERE igdb_id = 106797 ON CONFLICT (game_id, language_code) DO NOTHING;
