INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Songs2See', 'Songs2See is a fun and easy way to learn a musical instrument. It is the first music game that lets you play along to well known songs using real acoustic instruments. The only required hardware is a simple PC microphone and your instrument.' FROM games WHERE igdb_id = 16634 ON CONFLICT (game_id, language_code) DO NOTHING;
