INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('solaris--1', 128704, '2013-09-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x66.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7kad.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solaris', 'become a part of a world of color, light, and aural adventure: solaris.  create, destroy, move and manipulate the objects and surroundings at your disposal. watch as colors pulse across your screen, listen as the sound and music shifts based on what you want to see and hear. solaris is a living canvas for you to explore and change.  in this world, death is a concept that does not exist. there are no threats waiting to sneak up on you. nothing wants to see you defeated. there are no bosses, and there is no true ending. there is no pressure, and you are not required to "play" a certain way. the only thing that exists is you and the experience you wish to create.' FROM games WHERE igdb_id = 128704 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 128704 AND c.slug = 'alpha-six-productions' ON CONFLICT DO NOTHING;
