INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('micy-roll', 50798, '2013-05-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2v0e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3k44.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Micy Roll', 'Steer Micy in exciting landscapes, explore a whole new world, overcome obstacles to finally reach the highest mountain and fly into space.  In this universe, ink gives you wings. Collect a maximum of ink blots to jump and advance from a level to the next. Will you discover the secrets of the red moon?  Features:  - 47 levels to unlock (including 8 bonus levels)  - 200 ink blots to collect throughout this universe  - 3 main ambiances  - 10 secret places to explore’  - Funny Easter eggs  - 4 hidden keys to find in order to reach the ending  - A dreamy soundtrack  No actual ink was drunk in designing the game.  No mouse was hurt and no Moon was reached either !  A difficult challenge awaits you...' FROM games WHERE igdb_id = 50798 ON CONFLICT (game_id, language_code) DO NOTHING;
