INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WhiteWater 3D', 'Fun, fast paced down river whitewater kayaking game. Race against friends or go solo and unlock new kayaks and discover new unique items for your character. Fun trick / stunt mechanics and real water physics simulation make this river runner a frantic fantastic game to play with friends and family.' FROM games WHERE igdb_id = 303748 ON CONFLICT (game_id, language_code) DO NOTHING;
