INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Help Me Fly', 'Propeller Joe''s plane ran out of power again, and it''s up to you to help him jump‑start it through dozens of brain‑teasing levels. Arrange and rotate pieces on the board to connect Joe''s plane to the battery, collecting stars along the way to unlock new worlds. With charming cartoon visuals and intuitive touch controls, the game offers a relaxing yet challenging puzzle experience free from ads or in‑app purchases.' FROM games WHERE igdb_id = 240832 ON CONFLICT (game_id, language_code) DO NOTHING;
