INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cops N Robbers', 'The most popular pixel style gun shooter game with pocket edition is online. Custom skins, weapons, maps, armors, block style graphics...Bring you epic FPS game experience.  Cops N Robbers (FPS): 3D Pixel is one of 3D multiplayer shooting games developed by JoyDo Entertainment. If you are fond of multiplayer games, if you wanna download free games, if you want to have extraordinary jail break experience through FPS games and battle games…That''s it!' FROM games WHERE igdb_id = 89136 ON CONFLICT (game_id, language_code) DO NOTHING;
