INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Do Not Fall', 'Have you got what it takes to try out this challenging, intense and fast paced action-platform game? Think fast and think quick of where you are running as the tiles will start to disappear the moment you walked on it and the obstacles will be in your way to block you or knock you over. You can run. You can dash. You can jump, but whatever you do, DO NOT FALL!' FROM games WHERE igdb_id = 36154 ON CONFLICT (game_id, language_code) DO NOTHING;
