INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gt-racing-2-the-real-car-experience', 38939, '2013-11-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2f7j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tgeemhwc4b0ledn2bdrw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GT Racing 2: The Real Car Experience', 'GT Racing 2: The Real Car Experience is a true-to-life automotive journey featuring the most prestigious cars in the world!  The best-selling franchise is back for free and it''s designed to offer an unprecedented level of driving enjoyment, whether playing solo or multiplayer.  LEADERSHIP: POSSIBLY THE BEST HANDHELD RACING SIMULATION  • The richest handheld racing simulation game this year: 71 licensed cars on 13 tracks, including the real Mazda Raceway Laguna Seca.  • A superb collection of real cars from over 30 manufacturers: Mercedes-Benz, Ferrari, Dodge, Nissan, Audi, Ford, and more.  • Test your driving skills by completing 1,400 events, including Classic Races, Duels, Knockouts and Overtakes.  • 28 new challenges each week: improve your driving skills & maybe win a new car for free!  AUTHENTICITY: A DEEPER DRIVING SENSATION  • The new physics model offers the most realistic car dynamics ever offered in a handheld game.  • The sun is not always shining in GT Racing 2: Our tracks have different times of day and weather conditions.  • Race your way by choosing from among 4 different cameras, including a breathtaking interior view, and feast your eyes on real car designs!  • No repair times or repair costs! We won''t make you wait or pay to race in an event again.  EXPERIENCE: ENJOY THE RIDE SOLO OR IN MULTIPLAYER  • Compete with your friends or with real players from all over the world. Earn the fastest time on each race in multiplayer!  • Join teams to play with other drivers and accomplish common goals.  • New racer? Turn on Steering & Braking Assistance to get up to speed in a flash!  • Veteran driver? Tweak your performance in the garage with tons of custom options!' FROM games WHERE igdb_id = 38939 ON CONFLICT (game_id, language_code) DO NOTHING;
