INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Campaigns - Bulge ''44', 'Bulge ''44 is the second paid release in the Touch PzC series. This release includes 15 historical and hypothetical scenarios based on the PC Panzer Campaigns game of the same name. These scenarios allow you to play the part of different German commanders during the battle against the AI commanding the Allies. The scenarios range from the attacks by Peiper in the north of the Bulge to the attacks by 2nd and 116th Panzer further south as well as Panzer Lehr.' FROM games WHERE igdb_id = 106798 ON CONFLICT (game_id, language_code) DO NOTHING;
