INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Droidscape: Basilica', 'Droidscape: Basilica is a unique puzzle-arcade game set in the grim electropunk future. A power-hungry Ecclesiarchy has plunged humanity into a new Dark Ages. The last remaining Chronomancer has been taken hostage on the gargantuan Basilica space station, and if he dies, an already dark world will get a lot darker. Only a small, unarmed droid named Bishop 7 can save him-and only with your help.' FROM games WHERE igdb_id = 257259 ON CONFLICT (game_id, language_code) DO NOTHING;
