INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Not Pacman', 'Ever wondered how Pacman would be like with physics? No? Well, it''s revolutionary. This mashup of "Not" and "Pacman" puts The Pac and the Ghosts in a Pacworld cage, at mercy of gravity and the level''s shape, controlled solely by you. Ghosts still don''t like you very much, so you should be careful to make Pacman avoid them.' FROM games WHERE igdb_id = 135091 ON CONFLICT (game_id, language_code) DO NOTHING;
