INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlackSoul', 'BlackSoul is a third person survival horror adventure game with an intriguing story that takes place somewhere in the English countryside: people have been turned into psychotic killers by an unknown infection and you must try to help Ava and Sean survive in the quarantined area and find out the truth about the infection. You won''t spend all your time on a killing spree, but you''ll need to solve many puzzles which will challenge you.' FROM games WHERE igdb_id = 50314 ON CONFLICT (game_id, language_code) DO NOTHING;
