INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moonlight Walks', 'This game is an English-language visual novel, digital storytelling involving images and text.  It takes place the summer before you go away to college, and you''re spending it visiting with your aunt and uncle on a small island in the Atlantic ocean. One night, while out taking pictures of the full moon, you meet a girl walking down the beach.' FROM games WHERE igdb_id = 51178 ON CONFLICT (game_id, language_code) DO NOTHING;
