INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Files : Echoes of JFK', 'Shed some light on the murky circumstances behind the death of journalist Jack Olsen, who was investigating the assassination of the most famous US president from the last 55 years.  After meeting with the American president, FBI Director Edward Castle needs your help for this TOP SECRET assignment.  You’ll take on the role of Special Agent Jane Sully, and your investigative talents and attention to detail will be your most valuable weapons in this high-risk investigation.' FROM games WHERE igdb_id = 122096 ON CONFLICT (game_id, language_code) DO NOTHING;
