INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Len''en Mugenri: Evanescent Existence', 'Len''en Mugenri ~ Evanescent Existence is a vertical-scrolling danmaku shoot ''em up and the first game of the Len''en Project. It was made by Trick Nostalgie''s sole member JynX and released for the Windows operating system. The trial version was released on 12 September 2013, followed by the full version on 18 November 2013 as a free download. It was developed and released concurrently with the second game in the series, Earthen Miraculous Sword. The game was made with inspiration from the Touhou Project' FROM games WHERE igdb_id = 125797 ON CONFLICT (game_id, language_code) DO NOTHING;
