INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty Happy Town', 'You have been appointed as the new city planner to help Hello Kitty build her supercute town. Discover new buildings, quests and mini-games with your favorite Sanrio friends such as Keroppi, Badtz-Maru, My Melody, Chococat and many more. Complete the mini-games to earn apples and speed up the building process.' FROM games WHERE igdb_id = 96208 ON CONFLICT (game_id, language_code) DO NOTHING;
