INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man: Ticket Mania', 'Over 30 years later, the PAC is Back and better than ever! This new video redemption piece brings back the classic PAC-MAN game concept but now rewards players with tickets or a gift card. Players acquire points by munching on as many of the familiar Pac-dots and fruits as they can while being chased by the ghosts; Inky, Blinky, Pinky, and Clyde. If successful in entering the ghost house, players can win the “PAC-POT” and are treated with a mesmerizing PAC-MAN animation. Options for the “PAC-POT” can include tickets or gift cards*. The cabinet is beautifully lit from top to bottom with multicoloured LEDs as well as a spectacular LED marquee that scrolls the classic 8-bit PAC-MAN animation.' FROM games WHERE igdb_id = 146284 ON CONFLICT (game_id, language_code) DO NOTHING;
