INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Miles Edgeworth: Ace Attorney - Shattered Glass', 'The world we live in is filled with contradictions. However, some worlds only exist to contradict our own. In a world where prosecutors and defense attorneys are now on opposite sides of the courtroom, is it still possible for the truth to prevail? It must be possible, for if not... Then what is the point to our existence?' FROM games WHERE igdb_id = 303030 ON CONFLICT (game_id, language_code) DO NOTHING;
