INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaikan', 'Kaikan is a doujin PC SHMUP released in 2013 by Zakichi, who has released several games under the name -kigekiyahonpo-. The game is inspired by Raizing games where medal collection occurs, but with a focus on vacuum effects on medals instead of needing to collect them by touching them like in a Raizing game. The game was created solely within Shooting Game Builder and features royalty free music from various artists to fill in the game''s soundtrack.' FROM games WHERE igdb_id = 147047 ON CONFLICT (game_id, language_code) DO NOTHING;
