INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tasty Tadpoles', 'Tasty Tadpoles is a deliciously addictive trial of survival. Tap your tenacious tadpole triumphantly through four puzzling ponds of peril. You''ll need fast fingers to flash past the fleet green tadpoles, a keen sense of cunning and craftiness as you clash with the angry yellow tadpoles along with tremendous timing and precision poking to swim under those tedious turtles. If push comes to shove you can always eliminate these eclectic enemies with the zap of an electric eel!' FROM games WHERE igdb_id = 175100 ON CONFLICT (game_id, language_code) DO NOTHING;
