INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '123Babycount', 'Your baby will begin learning to count so easily with this beautifully simple game. Bold and colourful illustrations will hold your little one''s attention while they count along from one to ten. Abacus numbers slide in along the top as baby lights up the images one by one. You''ll be surprised just how quickly you baby will engage with this game and begin to learn to count!' FROM games WHERE igdb_id = 89724 ON CONFLICT (game_id, language_code) DO NOTHING;
