INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flickers', 'Flickers is an abstract, atmospheric, timing-based 2D platformer following the journey of the player from the heart of a dying flower through a world blanketed in perpetual twilight. Jump between hovering sparks called "flickers" as you make your way through painterly environments to reach the moon and transform the world around you. Through a combination of sights, sounds, and gameplay, Flickers aims to create an emotional arc without telling a conventional story.' FROM games WHERE igdb_id = 50200 ON CONFLICT (game_id, language_code) DO NOTHING;
