INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugby League Live 2: Gold Edition', 'Experience all the emotion and adrenaline of world class Rugby League from quick match through to international competition, as you play your way to becoming a real superstar! Realism takes over as you’re propelled into the on-field experience through advanced life-like graphics, as you dominate the field with a selection of over 100 teams, you can almost smell the sweat of being in the action.' FROM games WHERE igdb_id = 197238 ON CONFLICT (game_id, language_code) DO NOTHING;
