INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maimai Green', 'Maimai is an arcade rhythm game developed and distributed by Sega, in which the player interacts with objects on a touchscreen and executes dance-like movements. The game supports both single-player and multiplayer gameplay with up to 4 players. It was released on May 24, 2013. The coloring of this work is light green on a white background. On July 11, 2013, it was automatically upgraded to the existing maimai machine through an online update method.' FROM games WHERE igdb_id = 60812 ON CONFLICT (game_id, language_code) DO NOTHING;
