INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'O Enigma da Esfinge', 'In this game, you control the hero of the adventure: Gus, an irreverent boy that goes back in time and ends up in Ancient Egypt. In the midst of his misadventures, Gus finds out that the Sphinx is a time machine that allows him to travel back home. But just like him, other people want to use the Sphinx''s time-traveling power for their own purposes. Gus must face many hardships and solve challenging puzzles to uncover the Sphinx''s Engima and return to the present.' FROM games WHERE igdb_id = 299113 ON CONFLICT (game_id, language_code) DO NOTHING;
