INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catachresis: A Way Too Scary Game', 'When Jeff, noted ghostologist, is called in late one night, he knows that he has a job to do. What he doesn''t know is that this job is the most important one he''s ever had. As the night goes on, the stakes increase, and when the deadwinds rise and the lights go out, Jeff might be the only person between humans and their total extinction.' FROM games WHERE igdb_id = 57301 ON CONFLICT (game_id, language_code) DO NOTHING;
