INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Storage Warfare', 'Have you ever heard of a Storage Auction? Well Storage Auctions are modern day treasure hunts. In Storage Warfare, you attend storage auctions and your goal is to locate the treasures buried within the storage units, and then turn a profit! Keep a close eye on what is in each unit, so that you have the best chance to turn a profit. Outbid, Outsmart and Defeat your opponents in Storage Warfare!' FROM games WHERE igdb_id = 303220 ON CONFLICT (game_id, language_code) DO NOTHING;
