INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heatwave', 'You are but mere words. Would you speak as with that mask, With what lies underneath? Heatwave is a short story set in the same world as Death Wore Endless Feathers. It takes place in a future California, where Dai Araiguma is playing a VR game in the middle of an abnormally tenacious heatwave.' FROM games WHERE igdb_id = 169894 ON CONFLICT (game_id, language_code) DO NOTHING;
