INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airport Simulator 2013', 'Step into the shoes of an airport employee and experience the exciting and challenging daily routine of aircraft ground handling.  Your tasks will include numerous jobs right at the apron and taxiway of a modern, major airport.  Handle catering, transport luggage and cargo, and make sure that the jet bridges are brought into position and the machines are refueled.  Are the aircraft’s wings icy? This will test your skills with de-icing vehicles. Once you have finished these jobs in the apron, use a pushback tractor to push the aircraft to the taxiway.' FROM games WHERE igdb_id = 100124 ON CONFLICT (game_id, language_code) DO NOTHING;
