INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LaserReimu', 'LaserReimu is a vertically scrolling shooter developed by voidProc, where the player controls Reimu Hakurei in her journey to restore Marisa''s magic tool. Reimu has two primary weapons: a three-way ofuda shot that spreads all over the screen, and secondary laser, where both can be executed at once or separately in two different formations: focused or unfocused. The game also provides 55 achievements which can be unlocked when the player fulfills certain conditions.' FROM games WHERE igdb_id = 324302 ON CONFLICT (game_id, language_code) DO NOTHING;
