INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infinite Dunamis', 'One day while returning home from a job in the Royal City, a gifted engineer by the name of Luke comes across a young woman being attacked in the cave near his village. After fending off her attackers, he attempts to pull her from a heap of discarded mechanical parts only to discover she herself is half robot! Somewhat curious about what he has stumbled onto, Luke decides to take her home and fix her up, but little does he realize the chain of events he is about to find himself tangled up in...!' FROM games WHERE igdb_id = 39013 ON CONFLICT (game_id, language_code) DO NOTHING;
