INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dice Jockey', 'Dice Jockey is a simple and addictive puzzle game where you score by forming sets of dice with matching sides facing up. To score, you will need to form sets of two adjacent 2''s, three adjacent 3''s , four adjacent 4''s, and so on. 1''s can be used to complete any set and combos can be made by adding the right dice to existing sets.' FROM games WHERE igdb_id = 175171 ON CONFLICT (game_id, language_code) DO NOTHING;
