INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thin Walls', 'Iki had lost her voice due to previous events and thus only speaks internally. She wakes to find herself alone in her home with only the comforting voice named -Lo who resides in the walls of her home. A thunderstorm rages outside her window and seems to create strange objects in her home. She may unravel the events that caused her trauma or let them consume her, all the while being pursued by a dark faced, yet familiar stranger.' FROM games WHERE igdb_id = 151790 ON CONFLICT (game_id, language_code) DO NOTHING;
