INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quento', 'Quento is a little math puzzler without ads aimed for kids and adults. Quento gives you the solution to a sum and you''ll have to do the math. To play, just swipe from a number to a + or - and to another number again. Stars are earned when the sum adds up to the challenge above and before you know it you''ve progressed a round!' FROM games WHERE igdb_id = 90205 ON CONFLICT (game_id, language_code) DO NOTHING;
