INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sled Mayhem', 'Action packed racer with awesome animation, tricks, wicked terrains, incredible snow effects, intense speed, full featured game editor, sharing, original music and tons more. Compete worldwide, perform stunts, wheelies, flips, spins, huge jumps, and survive incredible crashes. Toss the rider around with your finger and watch him tumble, roll, and slide after you wipe out! Hop into the editor and create complete new mountains with various themes to play around with. Draw terrain and caves with your finger, decorate with props then go nuts with your snowmobile!' FROM games WHERE igdb_id = 197998 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 197998 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
