INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jigsaw Boom', 'Put together challenging puzzles as quickly as you can in Jigsaw Boom! Open up this virtual box of jigsaw madness and piece together tons of different images. Change the number of pieces per puzzle, turn on rotating pieces, and choose from different categories in this incredible game. With an awesome atmosphere and beautiful images, each puzzle is sure to transport you to a peaceful place in Jigsaw Boom!' FROM games WHERE igdb_id = 25279 ON CONFLICT (game_id, language_code) DO NOTHING;
