INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blip 1977: The Digital Game', 'Blip 1977 is an accurate recreation of the 1977 electronic and mechanical toy. It can be single player or multi-player. Blip was at the time a simulation of tennis,ping-pong and the early Pong video game made by Atari. You can play against the "computer" or two opponents can play each other.' FROM games WHERE igdb_id = 175528 ON CONFLICT (game_id, language_code) DO NOTHING;
