INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Photos with Mario', 'Photos with Mario, known in Japan as Photo Together with Super Mario (Japanese: いっしょにフォト スーパーマリオ Issho ni Foto Sūpā Mario) is a free photography-based application released on the Nintendo 3DS, allowing players to take pictures of various Mario characters. It is the Nintendo 3DS''s first entirely Mario-centered application and was developed by the same teams behind Super Mario Galaxy, Super Mario Galaxy 2, and Super Mario 3D Land. The application requires 65 blocks of space to download and is compatible with special Mario-themed AR cards' FROM games WHERE igdb_id = 61573 ON CONFLICT (game_id, language_code) DO NOTHING;
