INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railroads of America', 'Enjoy a challenging railroad construction time management game in which you have the mission to build a big railroad across United States. Use various pieces of railroad, which you have to connect and use, to build a track for the train, from the start to the end station. As you play through the game, levels become more and more complex, as they start to feature terrain elements such as: rocks, water, tunnels.' FROM games WHERE igdb_id = 197733 ON CONFLICT (game_id, language_code) DO NOTHING;
