INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quizzitive', 'Quizzitive is an entertaining quiz, an addictive game, and a new way to test and improve your vocabulary! The goal is to master "1000 Words Worth Knowing" - words selected by Merriam-Webster editors to challenge, intrigue, and contribute to a powerful vocabulary. Quizzitive offers 10 difficulty levels, with quiz types from "Speed Drill" to "Name That Thing." Master the words, beat your personal best, and see how your scores compare to the crowd.' FROM games WHERE igdb_id = 90287 ON CONFLICT (game_id, language_code) DO NOTHING;
