INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kisou Ryouhei Gunhound EX', 'In the future, everyone is scrambling for a new energy source called the Neutronpolymer. Beltonia, a tiny country that is moving toward democracy is discovered to hold large amounts of Neutronpolymer in their lands. To prevent the wars from getting out of hand, the authorities send the 9th Kisou Ryouhei regiment, called the Gunhound to the fray. This is a very small team, but their participation in the war efforts will change the path of the whole country.' FROM games WHERE igdb_id = 42872 ON CONFLICT (game_id, language_code) DO NOTHING;
