INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Use Holy Water!', 'The undead are on a rampage and the only thing stopping them is you, a shotgun, and a few bottles of holy water! (well yes you also get shurikens, lightning, and acid rain) Featuring five difficulty settings and two gameplay modes, Use Holy Water is a great way to kill some time by killing some zombies!' FROM games WHERE igdb_id = 243961 ON CONFLICT (game_id, language_code) DO NOTHING;
