INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Epic', 'Mahjong Epic has been enjoyed by millions of people for more than seven years. This new and free Mahjong sequel brings the game to all new heights! Because of its simple rules and engaging game play, Mahjong Solitaire has become one of the most popular games in the world. Whether you only have a few minutes to spend, or many hours, Mahjong Solitaire Epic is your perfect companion!' FROM games WHERE igdb_id = 83414 ON CONFLICT (game_id, language_code) DO NOTHING;
