INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doomworld Mega Project 2012', 'Doomworld Mega Project 2012 (originally named just Doomworld Mega Project) is a collaborative megawad, containing 40 maps from 40 different mappers from the Doomworld forums. The project was started by TimeOfDeath on March 13, 2012, the first version was released on December 16, 2012, and the final version was created on January 29, 2013. The completed WAD was uploaded to the /idgames archive on March 1, 2013.' FROM games WHERE igdb_id = 260955 ON CONFLICT (game_id, language_code) DO NOTHING;
