INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alien-spidy-between-a-rock-and-a-hard-place', 9966, '2013-07-25', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9xdq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Spidy: Between a Rock and a Hard Place', 'Now unlock 3 more ridiculously difficult “Special” levels, which are set to test your ability and skill to the very extreme! Once again you are set a challenge that has you travelling through the Forest, but this time there is no mercy! The smallest mistakes will send you right back to the start of this most brutal and unforgiving level. If you really think that you have what it takes to get Spidy from A to B then be our guest… Determination is what you will need when you are dropped straight into an underwater cave! No wait, determination and a lot of speedy quick reflexes, because without these there is certainly no way you can beat this level. Challenge accepted? Until now Spidy has never felt so helpless. You have to guide him out of the deepest and darkest depths of the caves; there is no sign of life anywhere! Don’t be miss lead, there is still plenty of danger this far into the earth’s crust, as you are in far less control due to wind tunnels, floating spores and unstable stalactites. You’ll be more than happy to reach the end, if you can?!' FROM games WHERE igdb_id = 9966 ON CONFLICT (game_id, language_code) DO NOTHING;
