INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stickman-tennis', 198010, '2013-05-22', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stickman Tennis', 'Stickman Tennis is a fast paced realistic tennis game on spectacular courts and an astonishing atmosphere, simple controls and tons of replay value. Play top spins, slices, lobs and smashes, play cross, longline or inside-out and choose between automatic and manual running. The revolutionary time machine will let you replay a point you lost, to give you a second chance. Play a quick game or complete tour season of Tennis against 100 different opponents. Collect trophies and improve your world rank in a complete season with 64 tournaments.' FROM games WHERE igdb_id = 198010 ON CONFLICT (game_id, language_code) DO NOTHING;
