INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Patchman Adventures', 'An adventure through 50 levels of dragons, bridges and dangers. Suitable for all ages. Clear the way by touching objects. Collect all the buttons to unlock more levels. 50 addicting & fun levels. The last 20 levels will really challenge your tapping skills.' FROM games WHERE igdb_id = 174237 ON CONFLICT (game_id, language_code) DO NOTHING;
