INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thapster', 'A rhythm game released in Thailand on iOS in 2013, and Android in 2014. It was also released globally on the PlayStation 3, and Xbox 360 in mid-2014. The mobile app has ended its services in 2017. The game uses touch controls to hit keys coming towards the screen across 3 tracks on basic up to 5 tracks on expert.' FROM games WHERE igdb_id = 86224 ON CONFLICT (game_id, language_code) DO NOTHING;
