INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lakeview Cabin', 'Murder RPG set in the shady town of Lakeview Valley. See how you''ll do as a new home owner in the Valley, where everyone seems to have a secret. Become the toast of the town or succumb to your dark desires. The choice is yours. But however you choose to play, beware... There is something evil lurking beneath the surface...' FROM games WHERE igdb_id = 128664 ON CONFLICT (game_id, language_code) DO NOTHING;
