INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Numberama 2', 'Numberama 2 is the good old puzzle and probably the best time killer, that was popular in the universities and colleges at the 80''s and 90''s. The objective is to cross out neighbouring (vertically or continiously) pairs of digits to completely empty the screen. You can cross out the same numbers or the ones that give a total of 10.' FROM games WHERE igdb_id = 200100 ON CONFLICT (game_id, language_code) DO NOTHING;
