INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elite-mastermind', 175500, '2013-10-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elite Mastermind', 'Put your thinking cap on and become a true Mastermind! Download Elite Mastermind and discover - or re-discover - this timeless board game classic on iOS! No confusing menus or hassle-filled frills, just pure strategic gaming fun! Grab a virtual peg and get playing today! The best mobile Mastermind gaming experience is here! Play solo or online against live opponents! Mastermind has never been more accessible or easy to play on the go with Elite Mastermind. The game is simple - players have eight rows to guess the position and color of four uniquely colored pegs. Deductive thinking and logic are key to success, but getting started is as easy as selecting either a 1 player or multiplayer game, grabbing some pegs, and playing! Elite Mastermind boasts casual gameplay complete with vibrant graphics, intuitive controls, and the freedom of ‘instant start-up’ gaming without having to create an account or even log into Game Center in order to start playing!' FROM games WHERE igdb_id = 175500 ON CONFLICT (game_id, language_code) DO NOTHING;
