INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('18-cadence', 63378, '2013-04-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5uvf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '18 Cadence', '18 Cadence is an experiment in interactive narrative, asking players to build something from pieces of story. There was a house at 18 Cadence Street. It was built in 1900. It burned to the ground in the year 2000. In between, people lived there: soldiers, mothers, bankers, stoners; people with secrets, with chores, with dreams, with regrets, with too much stuff or not enough, with sleepless nights, with laughter and with each other. In 18 Cadence, you can explore a century of living and assemble your own story from thousands of narrative fragments. Capture one life or juxtapose people from different eras. Slide, position, and recombine details like magnetic poetry. Decide what''s worth telling, and what should be left out. What story will you tell?' FROM games WHERE igdb_id = 63378 ON CONFLICT (game_id, language_code) DO NOTHING;
