INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Fantasy: The Forest of Doom', 'Nostalgia overload! Fighting Fantasy returns with Ian Livingstone''s classic, The Forest of Doom. Take part in one of the classic gamebook experiences that introduced a whole generation to fantasy role-playing games! Computer gaming was in its infancy and it was the early days of tabletop RPGs when The Forest of Doom exploded into bookshops in the early 80s, proudly displaying Iain McCaig''s iconic cover.' FROM games WHERE igdb_id = 175216 ON CONFLICT (game_id, language_code) DO NOTHING;
