INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Artisan Adventure', 'Artisan Adventure is thrilling, innovative new Adventure/Role-Playing Game. Unlike the traditional adventure, here you are free to choose your adventures, featuring a non-linear storyline that will take challenge the Hero with tons of challenges. In the world of Artisan Adventure you are free to go train various skills or go slay the most powerful monsters that threaten the existence of your beloved town.' FROM games WHERE igdb_id = 197810 ON CONFLICT (game_id, language_code) DO NOTHING;
