INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uotamuosu', 'Uotamuosu is a Yume Nikki fangame. It stars three protagonists: Shiwasu, Bill and Takatsuki. Each one of them has his own locations and stories. You have to go through Shiwasu''s scenario first, then Bill''s and finally, Takatsuki''s.' FROM games WHERE igdb_id = 202341 ON CONFLICT (game_id, language_code) DO NOTHING;
