INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star and Light', 'Play as Adhara and resolve the Deathlight puzzles of the Old abandoned Olorun Temple. Star and light features more than 28 secret achivements , a new game+, Mini-games , more than 30 levels , different costumes , collectibles , enigmas and more You''ll find a gameplay with a story and cut scenes/dialogues in 2d ,a secret dungeon to unlock etc.' FROM games WHERE igdb_id = 134508 ON CONFLICT (game_id, language_code) DO NOTHING;
