INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Dolphin Show', 'Now’s your chance to become a dolphin trainer! With more than 20 million downloads, My Dolphin Show is loved by dolphin fans all over the world! Teach your dolphin incredible tricks, then put on shows that will make the audience go wild. Your performances will take you through seven awesome locations including Las Vegas and Hawaii, where you’ll get the opportunity to show off your dolphin’s new skills!' FROM games WHERE igdb_id = 86773 ON CONFLICT (game_id, language_code) DO NOTHING;
