INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IL-2 Sturmovik: Great Battles', 'IL-2 Sturmovik: Great Battles is the continuation of the legendary IL-2 Sturmovik series that has set the standard for PC combat flight games for more than ten years. This new entry into the series will offer virtual pilots an even more accurate simulation of the most famous air battles of World War II. Better quality of content, bigger scale, new physics, more realistic aerodynamics and new game elements set this title apart from all which came before. We have only one goal - To give you a New Higher Level of Immersion!' FROM games WHERE igdb_id = 125836 ON CONFLICT (game_id, language_code) DO NOTHING;
