INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supersonic HD', 'Race on tracks created from your own music! Supersonic HD is an adrenaline-charged, music-driven 3D ride game. Blaze through radiant neon racing circuits at ever faster speeds, accompanied by electronic beats from Finnish artist collective Kitkaliitto. The ultimate challenge comes in the 30-second Blitz mode with speed boosts, time extends and other special collectibles.' FROM games WHERE igdb_id = 197682 ON CONFLICT (game_id, language_code) DO NOTHING;
