INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Time: Rock Bandits', 'The Ice King and his band couldn’t get any fans of their own, so they kidnapped Marceline’s audience instead. Help Finn and Jake rescue the stolen fans as you follow the Ice King’s tour across the Land of Ooo. Battle your way through the Dark Forest, Lumpy Space, Bad Lands, and the Ice Kingdom. Use Finn’s sword and Jake’s stretchy powers to slash, smash, and bash the bad guys in this action-packed side-scrolling platformer.' FROM games WHERE igdb_id = 16597 ON CONFLICT (game_id, language_code) DO NOTHING;
