INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen Training', 'Zen Training is a beautiful and unique puzzle game. The title combines puzzle dynamics with those of a rhythm-game. It has been designed to be the definitive pastime. The game is set in a classic Japanese Zen garden and is based on the concepts of Order and Chaos. In the heart of the garden there is a maple tree around which are located 5 stones with 5 different colored symbols to which correspond “mana stones” falling from the tree. The player''s task is to match symbols and colors in order to promote Order and Harmony, flowing trough an infinite series of standard and bonus levels.' FROM games WHERE igdb_id = 316067 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 316067 AND c.slug = 'crescent-moon-games' ON CONFLICT DO NOTHING;
