INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Google: Image Breakout', 'Google: Image Breakout was an online game built into Google Images that could be accessed by typing "Breakout" into the search tab. The game was a version of the game Breakout by Atari, but every block is a Google Image result for the game.' FROM games WHERE igdb_id = 225628 ON CONFLICT (game_id, language_code) DO NOTHING;
