INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sity', 'Sity is a Japanese Yume Nikki fangame. The game stars Mutsuki, a boy who cannot leave his room. The goal is to collect 16 effects in the dream world to unlock the various endings. This game has many elements related to modern cities and earthquakes.' FROM games WHERE igdb_id = 202332 ON CONFLICT (game_id, language_code) DO NOTHING;
