INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('c64-quiz', 134400, '2013-08-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28mn.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'C64 Quiz', 'The one and only c64 Quiz. If you can handle this game,then you my friend are a real old school NERD. You think you played them all. Really them ALL.!!!!!! No way. Go ahead. Give it a shot. You got 90 seconds.  Challenge your friends (if you have any ! ) in a multiplayer game.  This game is not for your common Playstation, X-Box, PC, "I don''t know what a Quickshot Pro is" wannabe NERDS. This is for real "I don''t wanna go outside it is 1984 and I broke my second joystick playing Combat School" NERDS.  you could be the ONE! The ONE who played them all.... 64k RAM.. old school awesome!  LOAD "c64 Quiz",8  RUN' FROM games WHERE igdb_id = 134400 ON CONFLICT (game_id, language_code) DO NOTHING;
