INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gurk-iii-the-8-bit-rpg', 200671, '2013-08-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4qmc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgy4j.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gurk III: the 8-bit RPG', 'The long-awaited sequel to the also-long-awaited sequel to the beloved 8-bit RPG has finally arrived! The third installment in the series is a bigger adventure than ever before, with loads of new monsters and items, many with unique effects and abilities. Character classes are better-differentiated and combat tactics are more subtle and interesting without sacrificing the hack''n''slash ethos that Gurk fans adore. The dedication to 8-bit culture remains fervent, with the complete 20-song soundtrack rendered with analog synth emulators that will evoke the classic sounds of the game systems of the 1980s. It''s all enough to justify the outrageously steep $2 price tag, so pay up and get Gurkin''!' FROM games WHERE igdb_id = 200671 ON CONFLICT (game_id, language_code) DO NOTHING;
