INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Look and Find: Elmo on Sesame Street', 'This is an interactive games app, which will help teach your child observation and memory skills in a fun and engaging way.  Look and Find Elmo on Sesame Street is a new educational app from the creators of Potty Time with Elmo. In this app, everyone’s favorite furry red monster needs help finding things that go HONK! and BOING! and CLANK! With Elmo as their guide, preschoolers can develop hand-eye coordination while looking for silly things on Sesame Street.' FROM games WHERE igdb_id = 88402 ON CONFLICT (game_id, language_code) DO NOTHING;
