INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solitaire Deluxe 2', 'Solitaire Deluxe 2 is the only leading solitaire game to offer Klondike (classic solitaire), along with the 20 other most popular solitaire variations in the world, including Spider, FreeCell, Tri-Peaks, Pyramid, Canfield, Golf and more. All of your solitaire favorites, and all with simple tutorials. And now it’s social: Have fun playing with friends, or play solo. Use the Currents feed, Facebook and GameCenter to keep up with your friends, or challenge them to the exact same deal you just won. Your mobile device has advanced… isn’t it time your solitaire did, too?' FROM games WHERE igdb_id = 88855 ON CONFLICT (game_id, language_code) DO NOTHING;
