INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('angelica-weaver-catch-me-when-you-can', 9975, '2013-01-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21s8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sidhbypwhzqvixhhufsk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angelica Weaver: Catch Me When You Can', 'Building on the successes of their award-winning Midnight Mysteries adventure series, MumboJumbo has created an all-new adventure franchise. Boasting interactive backgrounds, story-driven puzzles, an animated main character, voice acting and a rich narrative filled with twists and turns, Angelica Weaver: Catch Me When You Can is action-packed and sure to be another hit! Angelica Weaver, a detective on Chicago’s Special Task Force, must use her renowned deductive skills to stop a present day killer. The only way for her to get ahead of this killer is to first identify a murderer who escaped justice over a hundred years ago. Angelica has the ability to connect with the dead. Through supersensory visions she is able to jump back and forth between crime scenes on the streets of historic London and present-day Chicago where the victims reveal to her their final moments. Work with Angelica as she puzzles her way through the past and uses her insights to stop the pattern in the future in this hidden object puzzle adventure. Angelica actively participates as you explore detailed environments and sift through hidden-object scenes for clues. Using Angelica’s journal and a highly developed hint system, close the case in the present and in the past, by piecing together game-changing information for an unexpected twist. Angelica Weaver’s intriguing story is complemented with stunning visuals and sound effects that captivate and surprise. This compelling adventure, full of challenges and dozens of unique puzzles, delivers yet another thrilling experience from MumboJumbo.' FROM games WHERE igdb_id = 9975 ON CONFLICT (game_id, language_code) DO NOTHING;
