INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Pipes Evolution', 'X-Pipes Evolution is a revamped version of the old Factor Software''s classic MacPipes. It keeps the same familiar gameplay of it successful predecessor while adding eye-poppin'' cartoonish graphics, mind relaxing music and high quality sound effects. In this game you play the role of a tiny robot plumber called Roderick in a quest to solve plumbing problems scattered over several different worlds. Your goal is to hook up pipe parts on a grid to create a pipeline of required length before the fluid reaches the last connected pipe. Can you help Roderick save his universe from flooding?' FROM games WHERE igdb_id = 22028 ON CONFLICT (game_id, language_code) DO NOTHING;
