INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stardom: Hollywood', 'Stardom: Hollywood is a huge new adventure in a huge new city. Hollywood is bigger and better than ever: visit all-new restaurants, clubs and movie studios, flirt and network with other famous actors to get the best roles, customize your home with cool designer furniture, avoid the paparazzi, and get famous in new movies and TV shows. Your favorite characters are back with new quests, along with a bunch of new people and stories.' FROM games WHERE igdb_id = 87407 ON CONFLICT (game_id, language_code) DO NOTHING;
