INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catan: Creator''s Edition', 'Play the classic board game Settlers of Catan and its expansions Seafarers and Cities & Knights in Catan: Creator''s Edition. Create your own empire on Catan, including individual maps and scenarios. Let the new, detailed graphics take you to an utterly realistic Catan, or choose the classic mode for a genuine board game feeling. Let your imagination run free and create your own Catan world including new scenarios and maps.' FROM games WHERE igdb_id = 16539 ON CONFLICT (game_id, language_code) DO NOTHING;
