INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Become a Great Artist in Just 10 Seconds', 'Have you ever dreamed of being an Artist? Although this was not possible before, now it is because we have made a computer program. Let your imagination soar in Sketch mode, or take a 10-second Exam in which your imagination is subjected to the brutal and arbitrary standards of an unfeeling public under unreasonable time pressures.' FROM games WHERE igdb_id = 139817 ON CONFLICT (game_id, language_code) DO NOTHING;
