INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mirai-dagakki-futuretomtom', 140962, '2013-06-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kfz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8r3i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mirai Dagakki FutureTomTom', 'Mirai Dagakki FutureTomTom is a short lived drumming game from Konami in their BEMANI franchise. The cabinet consists of 4 tom-tom drums in a row where one or two players play in time with falling objects in the screen.  The game features a couples mode where notes are placed in such a way that you often end up hugging the other player (with one player playing the inner two drums while the other having the outer two drums), in this mode you are scored not only on how well you were doing, but your compatibility.  The game makes use of a kinect camera to show you drumming in the background of the game, as well as creating a collage of your performance that you can retrieve from the eAmuse app at the end of the game. The camera is also used for special gesture commands in some songs.' FROM games WHERE igdb_id = 140962 ON CONFLICT (game_id, language_code) DO NOTHING;
