INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slot Revolution', 'Travel to a world of fantasy filled with powerful creatures and ageless magic in this addicting slot machine-based, role-playing experience! Do you have what it takes to turn back the tide of blood that threatens your once peaceful world? Become a Warrior, Ranger, or Wizard, each with different skills and abilities! Join forces with friends and allies to take advantage of strength in numbers and leap into action to defeat enemies, earn gold, and find new gear and equipment.' FROM games WHERE igdb_id = 296034 ON CONFLICT (game_id, language_code) DO NOTHING;
