INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Doumeiju: Mystical Power Plant', 'Touhou fangame and second game in the Kaisendo series. The main gameplay mechanic of Mystical Power Plant is based around collecting leaf items to fill a gauge, which causes the player to ''level up'' and gain various benefits as the game proceeds. The benefits vary depending on what character duo is chosen.' FROM games WHERE igdb_id = 246671 ON CONFLICT (game_id, language_code) DO NOTHING;
