INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Can Knockdown 3', 'Be accurate! Be smart! Be quick! Challenge your aim, hone your precision, and push your puzzle-solving skills to the next level in this insanely addictive game. This installment takes the critically acclaimed Can Knockdown series to all new heights- the physics-based carnival gameplay you know and love- and adds unique puzzles, adrenaline-charged challenges, and even more explosive action!' FROM games WHERE igdb_id = 96722 ON CONFLICT (game_id, language_code) DO NOTHING;
