INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Millefiori', 'The main character, Kojirou, is an average student. Rikana Millefiori, a friend of his who stopped going to school, suddenly calls him one day to arrange a meeting. From there, they start hanging out together. Spinoff of the game Mix Ore, following the events before and after Rikana''s route.' FROM games WHERE igdb_id = 150155 ON CONFLICT (game_id, language_code) DO NOTHING;
