INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yousei', 'For the past few years, Kangai has been a wanderer, but his return to his hometown has triggered a series of deaths linked to his past. He joins a group of psychic teenagers who solve mysteries under the watchful eye of the government. In Yousei, he and his group are sent undercover to a local university where they must dig up the remains of a top secret experiment. Upon arrival, they discover the project lead missing, and an old acquaintance racing them for the same information.' FROM games WHERE igdb_id = 62968 ON CONFLICT (game_id, language_code) DO NOTHING;
