INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeon-dashers', 10252, '2013-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/maihtbpszpubzcsunmtb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Dashers', 'Dungeon Dashers is a fast-paced turn-based dungeon crawler, bringing the enjoyment of a tabletop board game with friends to the PC. The game''s design streamlines the core dungeon crawler experience to its essentials, for an intense, loot-grabbing adventure.  Accumulate wealth by smashing boxes full of gold, slaying monsters, and looting glowing chests. Use your gold to buy consumables to boost your abilities or craft upgrades for your equipment. Find new swords, bows, staffs, spells and other equipment hidden in chests obscured by challenges and quests.' FROM games WHERE igdb_id = 10252 ON CONFLICT (game_id, language_code) DO NOTHING;
