INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LP Recharge', 'LP Recharge, also known as Linkin Park Recharge, is a free-to-play action-puzzle game, developed by Swiss studio Kuuluu Interactive Entertainment, which is composed by American rock band Linkin Park. The game was released on September 12, 2013, as it is a current playable game on Facebook. The game is focused on solving puzzles and also attempting to raise awareness about parts of the world that don’t have reliable power.' FROM games WHERE igdb_id = 227970 ON CONFLICT (game_id, language_code) DO NOTHING;
