INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pretty Rhythm: Rainbow Live Kira-kira My Design', 'Pretty Rhythm: Rainbow Live: Kira-kira My Design features the main female cast as playable characters along with a new character, Cosmo Hojo, as well as the female cast from Pretty Rhythm: Aurora Dream and Pretty Rhythm: Dear My Future. The limited edition of the game came with an exclusive Prism Stone featuring the Miracle Fantasy Rainbow Dress, which was usable on Pretty Rhythm arcade machines.' FROM games WHERE igdb_id = 177581 ON CONFLICT (game_id, language_code) DO NOTHING;
