INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter''s Trophy 2: America', 'More complete, fun and realistic than ever, the Hunting Challenge series has earned a reputation as the best hunting simulation for consoles. Realistic animal behaviour, a variety of environments, weapons, animals, hunting plans, equipment and skills to unlock, online leaderboards, training in shooting at fixed and moving targets… all are brought together to offer a unique gaming experience which will delight experienced and novice hunters as well as players just looking to experience something new.' FROM games WHERE igdb_id = 10420 ON CONFLICT (game_id, language_code) DO NOTHING;
