INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swing King', 'The King’s furry kingdom is in jeopardy. Time to swing into action! Fling the King across levels, through obstacles and traps to grab stars and reach his flying unicorn. Use simple touch controls to aim the King’s trajectory, move obstacles out of his way, and use power-ups such as the sticky grappling point and the boxing glove. Your kingdom is in trouble. What are you waiting for?' FROM games WHERE igdb_id = 16598 ON CONFLICT (game_id, language_code) DO NOTHING;
