INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contra: Locked ''N'' Loaded', 'Contra: Locked ''N'' Loaded is a run-n-gun shooter developed as an attempt to remake the original Konami classic, Contra, using the OpenBOR engine. It features more playable characters and 3 missions, with two additional stages that can be unlocked.' FROM games WHERE igdb_id = 221066 ON CONFLICT (game_id, language_code) DO NOTHING;
