INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweet 33', 'You''ll have to think fast and sweet-talk even faster to complete this epic love quest! You wake up all alone in the desert with only one thought in your mind: "I have to get married right this minute!" Luckily, a nearby building bearing the sign "Fangamer: Suite 33" is filled with potential significant others! Seek them out and woo them until you''ve captured their hearts! Who knows, your walk down the aisle might just be FANtastic!' FROM games WHERE igdb_id = 22707 ON CONFLICT (game_id, language_code) DO NOTHING;
