INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB 2K13', 'Major League Baseball 2K13 is a Major League Baseball licensed baseball simulation video game developed by Visual Concepts and published by 2K Sports and was released on March 5, 2013 for the PlayStation 3 and Xbox 360. The commentary is delivered by the trio of Gary Thorne, Steve Phillips, and John Kruk. David Price (then of the Tampa Bay Rays) is the game''s cover athlete. On January 6, 2014, 2K Sports announced that MLB 2K13 would be the final game in the MLB 2K Series' FROM games WHERE igdb_id = 7064 ON CONFLICT (game_id, language_code) DO NOTHING;
