INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sabre Wulf', 'One of the most beloved ZX Spectrum games of all time, this remake of Sabre Wulf stays faithful to the original - including the brutal difficulty! Alone in the jungle, you must find the four parts of the amulet to allow passage past the gatekeeper and escape. With deadly beasts jumping at you from all sides and the dreaded Wulf patrolling his territory, you certainly have your work cut out.' FROM games WHERE igdb_id = 214785 ON CONFLICT (game_id, language_code) DO NOTHING;
