INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polybius', 'A fan-made Atari 2600 game centered around the Polybius myth that was made by Lost Classics and distributed at Retro Gaming Expo 2013, and then distributed again by Hard Copy Games in 2018. Polybius is a unique game of skill and strategy. Take control of a computerized starship combat system to destroy a swarm of relentless alien enemies. Enjoy addictive gameplay with arcade-realistic graphics and sound. Challenge your friends and family to get the lowest possible score. Can you be the one to reach zero?' FROM games WHERE igdb_id = 246742 ON CONFLICT (game_id, language_code) DO NOTHING;
