INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cage Fight', 'Cage Fight is a parody of River City Ransom that pits MMA fighters against people who abuse animals. Take control of real MMA fighters Jake Shields, Aaron Simpson, and Georgi Karakhanyan to see if you have the moves to foil a secret underground animal testing ring in PETA''s game.' FROM games WHERE igdb_id = 257406 ON CONFLICT (game_id, language_code) DO NOTHING;
