INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-brief-history-of-the-world', 103565, '2013-07-25', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Brief History of the World', 'Take a sweeping ride through the history of mankind in the famous board game from Ragnar Brothers! Control the decisions of major leaders and conquer the world! Lead your empire to victory in this turn-based strategy game! Play as the character of Julius Caesar, Genghis Khan, or Napoleon Bonaparte and command armies through 6 riveting epochs in history, with 42 major empires and 15 minor empires. Choose from over 40 event cards to enhance replayability and alter the course of history. All set to an epic soundtrack (or listen to tracks from your own music library) with beautiful graphics and original artwork from the Ragnar Brothers’ board game. With no setup time required, no pieces to lose, and no arguments about the rules, the future of board games is here and A Brief History of the World gives you exactly what you want -- to play!' FROM games WHERE igdb_id = 103565 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 103565 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
