INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ballpoint-universe', 50861, '2013-06-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tuo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uckjl0euxcgzkxturc4d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ballpoint Universe', 'Ballpoint Universe is a side-scrolling shooter / platform adventure game about a doodle named Doodle. Every bit of the game has been drawn with a ballpoint pen to build immaculate environments. Classic space shooter gameplay! Shoot and dodge through a hell-storm of enemies to obliterate the deranged doodles and the Logician scourge. Fight for the future of creativity itself! Explore doodle realms, meet intriguing, eccentric characters, get hints and items to aid your quest. Upgrades! Fully fledged 4 slot customization system; customize your ship with the gear you acquire along your journey. Equip for the needs for a certain mission; do you need a shield and sword? sword and gun? Gun and gun? Exploit the enemy fleet''s weaknesses and overcome their systematic genocide of imagination!' FROM games WHERE igdb_id = 50861 ON CONFLICT (game_id, language_code) DO NOTHING;
