INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fukawa-chan', 'This is a fangame about one of the protagonists of the Danganronpa series. Touko Fukawa doesn''t have a fun life. In fact, she has a pretty miserable one. Between bullying, self-loathing, and mental illness, an average day in Touko''s life is very painful. And today, you get to follow her through it.' FROM games WHERE igdb_id = 170246 ON CONFLICT (game_id, language_code) DO NOTHING;
