INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pba-bowling-challenge', 88864, '2013-01-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lp13vza5mv1a3axnwib8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/raexlnze1rgjwvrglayr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PBA Bowling Challenge', 'Rise through the ranks against 22 of the PBA’s best bowlers as you compete for a variety of regional and national championship trophies. Starting in a local alley with a scuffed up 12 lbs ball, you’ll hone your skills against bowling legends on your way to competing in the Tournament of Champions!  Start a career or bowl a quick game! Career mode is at the heart of PBA Bowling Challenge, but if you’d rather just lace up and take to the lanes, we’ve got you covered. Choose from a wide variety of opponents and locations and unlock even more content in Career Mode!  Online Multiplayer Action! Bowl against your friends in real-time, one-on-one multiplayer matches! Powered by Game Center services, multiplayer mode lets you invite your friends or get matched against a random opponent! Bowl against the best! How do you think you’d fare against the cool confidence and pin-point accuracy of Walter Ray Williams, Jr. or the brash power stroke of Pete Weber? How would your scores stand up against the high spin and smooth release of Norm Duke or the high cranking backswing of Tommy Jones? Based on actual statistics that track their power, hook, and control, PBA Bowling Challenge strives to accurately recreate the skill and style of the top bowlers in the sport today. Features Include: - Quickplay, Multiplayer, and Career modes! - Dozens of PBA Tournaments! - Bowl against 22 of the best PBA bowlers! - Over 100 different bowling balls with unique stats! - Leaderboards and Achievements. - Bonus challenges in every tournament! - Split Balls, Bomb Balls, and more!' FROM games WHERE igdb_id = 88864 ON CONFLICT (game_id, language_code) DO NOTHING;
