INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apothecarium: The Renaissance of Evil', 'A hidden object game set in France. During the Middle Ages a terrifying, mysterious disease raged across Italy. It killed thousands of people, whole towns and villages perished together. There were legends of a mythical town of Apothecarium, where the secret to defeating the disease was hidden.' FROM games WHERE igdb_id = 59907 ON CONFLICT (game_id, language_code) DO NOTHING;
