INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QuestLord', 'QuestLord is a single player first person turn-based adventure game in the style of Dungeon Keeper etc. Or was developed in 2012 by Eric Kinkead and released on the iPhone. An Android release came in 2013.  In the game you are a QuestLord, an almost messianic figure destined to free the land of Norrab from cruel fate at the hands of the evil Lord Drazzik who plots to usurp the throne.' FROM games WHERE igdb_id = 38895 ON CONFLICT (game_id, language_code) DO NOTHING;
