INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Video Strip Poker HD', 'Strip poker with sexy girls in HD. Classic five card draw poker with girls who undress their clothes when you win. High definition interactive video you can play in fullscreen or in a window with game save feature. No real gambling, just for fun.' FROM games WHERE igdb_id = 109636 ON CONFLICT (game_id, language_code) DO NOTHING;
