INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('impetus', 266701, '2013-08-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7302.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Impetus', 'Released as part of LUDUM DARE #27, whose theme was "ten seconds", IMPETUS was a short-lived collaborative game in which players across the world worked together around the clock to keep a doomed astronaut alive for as long as possible. A player visiting the game''s page would be presented with a picture of the unnamed unconscious woman, and a countdown indicating how long she had yet to live. Any player clicking the prominent "click to keep alive" button would result in the countdown being reset: by working together, by ensuring that the button was pressed at least once every ten seconds, players could attempt to keep her alive. The game was victim of its success: after almost 12 hours of runtime, the traffic to the site reached such levels that it became inaccessible for more than ten seconds, resulting in the death of the character. The site remains accessible, but the game is no longer playable and only displays the end screen.' FROM games WHERE igdb_id = 266701 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 266701 AND p.igdb_id = 82 ON CONFLICT DO NOTHING;
