INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sheepland', 175269, '2013-10-10', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sheepland', 'Sheepland: a sunny land of rolling green meadows, lush forests, and majestic mountains. The peaceful, happy people of the island want nothing more than to roam the land with their fuzzy little flocks of fluffy white sheep. All is well and good, until somebody has the bright idea to put up some fences... Now the shepherds must compete for the most profitable lands to raise their flocks, driving the sheep to the lands they own and fencing them in so they don’t wander off and join some other shepherd’s flock! And then there’s that strange black sheep that keeps showing up. Its rare black wool is certain to fetch a pretty price in the market for the shepherd that can pen him in! Can you corral the finest herd in the best lands and become the richest shepherd in Sheepland?' FROM games WHERE igdb_id = 175269 ON CONFLICT (game_id, language_code) DO NOTHING;
