INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('endless-nights-rpg', 223628, '2013-12-30', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/scjkb6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Nights RPG', 'Endless Nights is a roguelike rpg that lets you play your way, with a skills-based system that recognizes the actions of your character in the game and develops those skills. This means you can choose to use a sword, or a mace, use magic or pray to the gods, and you never need worry about picking a class and no visiting trainers to ''learn'' new skills. You just play the game and the skills you use will increase as you play, and when you''ve learned enough of a skill, new skill trees and abilities will become available. Endless Nights is a role-playing game in the rogue-like tradition, which means randomized adventure areas, random dungeons and a different adventure each time you play the game. The TitanFire RPG system used in the game provides for strategic combat by putting an emphasis on defense and on developing strategies to break through the defenses of your opponent during combat. A tweak to the rogue-like style is the Profile system, which allows for a certain amount of permanence with the inclusion of profiles that allow you to carry over some gold or gems to a new character.' FROM games WHERE igdb_id = 223628 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 223628 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
