INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mach Storm', 'Mach Storm is a flight action arcade game set inside an immersive dome-shaped cockpit, later used for Star Wars: Battle Pod. Players take control of Storm 1, a pilot who must defend various major cities around the world from massive terrorist attacks. The game is based on the Ace Combat series and uses many assets from those games, but it is not directly tied to the series.' FROM games WHERE igdb_id = 124522 ON CONFLICT (game_id, language_code) DO NOTHING;
