INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charades!', 'Charades! is the outrageously fun and exciting multi-activity game for you and your friends! With different challenges from dancing, singing, acting or sketching - guess the word on the card that''s on your head from your friends'' clues before the timer runs out! With over 100 themed decks to choose from, many packed with over 400+ exciting gameplay cards, the fun will never stop! So whether you''re an artist, a singer, an actor, or a science nerd - there''s something for everyone. Challenging players in trivia and creativity, your next party, reunion or family game night will never be the same.' FROM games WHERE igdb_id = 88858 ON CONFLICT (game_id, language_code) DO NOTHING;
