INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Splinter Cell: Blacklist - Ultimate Edition', 'The United States has a military presence in two-thirds of countries around the world, and some of them have had enough. A group of terrorists calling themselves The Engineers initiate a terror ultimatum called the Blacklist - a deadly countdown of escalating attacks on U.S. interests. Tom Clancy''s Splinter Cell Blacklist Ultimate Edition includes: - Tom Clancy’s Splinter Cell Blacklist. - Tom Clancy’s Splinter Cell Blacklist High Power Pack. - Tom Clancy’s Splinter Cell Blacklist Homeland Pack.' FROM games WHERE igdb_id = 99926 ON CONFLICT (game_id, language_code) DO NOTHING;
