INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forget-Me-Not', 'Run around the infinite, ever changing corridors of the Neon Dunjun, gathering flowers and shooting everything. ZAP!  Grab the key to the next floor.. try not to let monsters take it off you. Once you''ve picked all the flowers, the doorway shall appear.. Grind the walls for a speed boost and the power of squishing! The edges of the maze wrap around - do try not to shoot yourself in the back.' FROM games WHERE igdb_id = 47269 ON CONFLICT (game_id, language_code) DO NOTHING;
