INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fleet Battle', 'This boardgame offers everything that made the classic so popular. Defeat ship after ship and rise through the ranks - from Seaman Recruit up to Admiral of the Navy. Pit yourself against the computer (singleplayer), random human opponents (Quick Match) or your friends (Play with Friends) and prove you have the makings of a real Fleet Commander. If you''re looking for a fun, fast-paced naval battleship-style combat game - look no further.' FROM games WHERE igdb_id = 272460 ON CONFLICT (game_id, language_code) DO NOTHING;
