INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Snap', 'Neon Snap is a simple to learn but challenging game of pixel-art themed puzzles made from tetrominos! Each puzzle is made up of seven different tetromino blocks, which all snap together inside each level''s grid to create pixel art shapes. Click and drag pieces onto the grid, rotate and move them around until they all snap together to complete each puzzle! Can you solve all 100+ levels?' FROM games WHERE igdb_id = 140597 ON CONFLICT (game_id, language_code) DO NOTHING;
