INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('assassins-creed-iv-black-flag-buccaneer-edition', 89872, '2013-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2tf6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/utnqyretttfv1fspm8il.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed IV: Black Flag - Buccaneer Edition', 'Welcome to the Golden Age of Piracy. The year is 1715. Pirates rule the Caribbean and have established their own lawless Republic where corruption, greediness and cruelty are commonplace. Among these outlaws is a brash young captain named Edward Kenway. His fight for glory has earned him the respect of legends like Blackbeard, but also drawn him into the ancient war between Assassins and Templars, a war that may destroy everything the pirates have built. A Brash Rebel Assassin: Become Edward Kenway, a charismatic yet brutal pirate captain, trained by Assassins. Edward can effortlessly switch between the Hidden Blade of the Assassin’s Order and all new weaponry including four flintlock pistols and dual cutlass swords. The Assassin’s Creed IV Black Flag Buccaneer Edition includes: A 45cm figurine of Captain Edward Kenway. Collector’s box. A high quality artbook including artworks that inspired the game. The Official Game Soundtrack. 2 lithographs in a protective envelope. Unlockable bonus content: 3 additional solo missions for an extra 45 minutes of gameplay: Black Island: Captain Morgan’s favourite ship has sunken off the coast with a full load of legendary sailing equipment. Explore the Black Island and retrieve these items Pirates have desperately been looking for. Hidden Mystery: Follow Stede Bonnet’s path and find the secrets of his adventures on the beautiful island of St Lucia. Sacrificed Secrets: Recover Captain Drake’s lost treasures, including golden flintlocks and cutlass when exploring the exotic island of Sacrifices. Additional Single & Multiplayer items: Captain Kenway’s Legacy.' FROM games WHERE igdb_id = 89872 ON CONFLICT (game_id, language_code) DO NOTHING;
