INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Rock Force', 'It was the year 20XX and Earth had finally achieved an extended period of peace. Wily had since vanished, permitting the world to once again focus on other matters: science, progress, and the ever growing relationship between humans and robots. However, Mega Man, now wary of true everlasting piece, recruited eight willing robot masters and began training them; if evil should dare arise, his team, the Rock Force, would be there to stop it.' FROM games WHERE igdb_id = 194382 ON CONFLICT (game_id, language_code) DO NOTHING;
