INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('you-still-wont-make-it--1', 79487, '2013-08-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vzxbza4wmdewud0pafi4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr949.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Still Won''t Make It', 'You Still Won''t Make It is a challenging instant-death platformer developed by Vetra Games, the sequel to You Probably Won''t Make It. The game includes three ''worlds'', each containing 18 levels, as well as the 18 ''classic'' levels from You Probably Won''t Make it, recreated for the new game. The player controls a small black creature through levels that fit without scrolling on the screen. Levels are unlocked by completing previous levels, but can be replayed at any time afterwards. The game has no plot, and new concepts in-game are introduced through specific levels and not explicitly. Levels are made difficult through the usage and placement of obstacles - mostly spikes - which all kill the player immediately upon contact (and shred the creature into bones and gibs). Most obstacles are static, requiring only accuracy in movement and careful jumps, but several include interactive objects or moving platforms - or, in one of the few concessions to the player, checkpoints. Levels are not timed, and there is no scoring, but the game displays a continual tally of the player''s deaths throughout the levels.' FROM games WHERE igdb_id = 79487 ON CONFLICT (game_id, language_code) DO NOTHING;
