INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Otomaid @ Cafe', 'Otomaid @ Cafe is a femboy maid cafe eroge. Kei agrees to take a part-time job at his brother Iori''s cafe. Then he learns that it''s a maid cafe run by crossdressers, and his cute coworkers are actually boys. He doesn''t understand why men would want to wear women''s clothing, but he''s about to learn.' FROM games WHERE igdb_id = 191361 ON CONFLICT (game_id, language_code) DO NOTHING;
