INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounders and Cads', 'Welcome to Bounders and Cads, a turn-based strategy game for players of all ages. Old Aunt Edna has died leaving a fortune to be claimed. The money will go to the one rascal who can play the dirtiest tricks and earn the most money in business dealings. Buy up businesses, sabotage your opponents, deploy tricky strategies, and swindle your way to an inheritance. Beware, though, Aunt Edna’s estranged husband, the Brigadier, is lurking about- and he’s very, very angry...' FROM games WHERE igdb_id = 10062 ON CONFLICT (game_id, language_code) DO NOTHING;
