INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherbet Thieves', 'Sherbet Thieves is a 2D indie game that combines twin-stick shooting and defense mechanics. As jetpack mercenary Proton Joe, the goal is to prevent sherbet pirates, space hippies with the munchies, and other aliens from stealing sherbet from Farmer Dan’s orbital farm. The player is paid in moonshine depending on how well they did at protecting the sherbet. Between levels weapons and upgrades can be purchased with this moonshine. There are 3 difficulty levels, 19 story-mode levels, and a never-ending survival mode.' FROM games WHERE igdb_id = 93634 ON CONFLICT (game_id, language_code) DO NOTHING;
