INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forever Lost: Episode 2 SD', 'Congratulations! You managed to escape from that… what was it? A hospital, a lunatic asylum? No, it was something else, was it... staged? Who built it? Who put you there? None of that matters right now, you must keep moving! No time to catch your breath, you just have to keep going! Have you won your freedom or are you just in another cage?' FROM games WHERE igdb_id = 100336 ON CONFLICT (game_id, language_code) DO NOTHING;
