INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('construction-simulator-2014', 86891, '2013-10-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/viljuptnewmhbiibqydc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cil1lrwordnhmvrnylh8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Construction Simulator 2014', 'Do you want to build houses and industrial buildings with heavy machines from LIEBHERR, MAN and STILL? Then get the Construction Simulator 2014 – in this way your iOS device becomes a virtual construction site. Playing the Construction Simulator 2014 you can take over the control of 14 construction machines which are true to the originals in high-quality 3D graphics. Excavate the foundation of a one-family house with realistic machines, operate a concrete pump which is as high as a house to cast concrete into the wall formwork of an industrial hall or place giant roof trusses with a mobile crane and show that you can keep a steady hand – more than 300 tasks promise more than 20 hours of gaming fun. Do you want to convert the small building company into a successful real estate group and bring your own style to the city where you can navigate freely? You can play the Construction Simulator 2014 on the following devices: - iPhone 4, 4s, 5, 5s, 5c, 6, 6 Plus - iPad 2, 3, 4 - iPad mini, iPad mini 2 - iPad air, iPad air 2 Features -14 construction machines from LIEBHERR, MAN and STILL designed true to the original with original operating modes -High-quality 3D graphics -Realistic control of the construction machines, optimally designed for mobile devices - for example, support of the euro control for excavators -Huge construction sites like wind generator, swimming pool, school building or town hall -For beginners and experts: Free change from Arcade control to professional control -Huge freely navigable world -Ladder of success: From apprentice to building tycoon -Highly variable order system guarantees never ending gaming fun Unblock the different districts of the city and bring your own style to the city and choose freely colour, material and specifications of the construction' FROM games WHERE igdb_id = 86891 ON CONFLICT (game_id, language_code) DO NOTHING;
