INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdoms Fall', 'Kingdoms Fall is an epic top-down action adventure game for iOS. You will get to explore an open world, finding items such as the Boomerang, Bombs, Grappling Hook and Fire Wand. You will need to venture into the realm''s darkest dungeons, conquer tricky puzzles, and survive intense boss battles to save your kingdom and everything you love.' FROM games WHERE igdb_id = 41489 ON CONFLICT (game_id, language_code) DO NOTHING;
