INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liberation Maiden: SIN', 'A sequel to Liberation Maiden, although it sheds the three-dimensional shooting gameplay in favor of a visual novel approach. Liberation Maiden SIN follows the exploits of Kiyoto Kaido, childhood friend of and newly-appointed chief aide to President Shoko Ozora, during the events of the Second Liberation War. Kaido has the ability to read other people''s minds. Several new female characters also appear as cabinet members in the New Japan government. Both the Liberator Kamui and the Guardian Spirits also feature.' FROM games WHERE igdb_id = 52548 ON CONFLICT (game_id, language_code) DO NOTHING;
