INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pool 3D', 'Pool 3D is a well thought – well designed pocket billiards for your Mac. The pool table invites you for an unlimited game of billiards and an everlasting feeling of fun.  Pool 3D comes with:  •Intelligent Player AI  •Decent and Realistic 3D effects and Graphics  •Awesome 8 Ball Game  •3 modes of Gameplay – Easy – Medium – Hard  •In-Game Achievements for a great challenge  •Flip around 4 Characters  •Change Cam View  Please leave a review and tell us your opinion so we can make it better!' FROM games WHERE igdb_id = 86900 ON CONFLICT (game_id, language_code) DO NOTHING;
