INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Challenge 2014', 'Ski Challenge 2014 is the 10th edition of the alpine skiing series Ski Challenge. The game includes the famous alpine downhill tracks of Bormio, Val Gardena, Kitzbühel, Wengen, Val-d’Isère, Garmisch-Partenkirchen, Beaver Creek and in celebration of the olmypic winter games Sochi. The goal for the players is to climb the leaderboards by getting the fastest times. Three day events were held on each track to determine race winners who would win physical prizes. The game also featured a parallel slalom track in Munich, which was used for a newly introduced duel game mode.' FROM games WHERE igdb_id = 87793 ON CONFLICT (game_id, language_code) DO NOTHING;
