INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '.ExE', '.ExE is an English Yume Nikki fangame. It stars Carrie, a girl who refused to leave her apartment. .ExE involves entering a dream world through the protagonist''s computer, with Carrie clicking on an application. Carrie takes on a different form in the dream world. The main objective is exploration and collecting effects.' FROM games WHERE igdb_id = 202236 ON CONFLICT (game_id, language_code) DO NOTHING;
