INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Search Puzzles', 'Best new FREE word search puzzle game in 2018! Challenge your brain with addictive & fun puzzles! Full of themes to suit your every mood!  Are you ready for adventure: - Treasure-huntin'' for some pirate-themed phrases? - Searching for words to survive the zombie apocalypse? Or maybe you''re just stopping by: - Say HI (or maybe not) with "words that rhyme with hello"! Putting on those nerdy glasses: - Stretch your vocabulary with a "Vocab Challenge" puzzle or two! But wait, there''s more! - Lots of other puzzles to choose from! - Replay categories to beat your own high-score! - Complete quests to get new FREE puzzles! Forget the pen and paper - You''ll never run out of puzzles with WORD SEARCH PUZZLES!  WARNING: Playing this game may challenge your brain and improve your word power :)' FROM games WHERE igdb_id = 88870 ON CONFLICT (game_id, language_code) DO NOTHING;
