INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glare', 'Glare is an action platformer with beautifully realized 3D environments. Summoned from starlight to defeat the infectious creatures called the Ramora, you play as the Shiner, a being of pure light given shape by an ancient suit of armor. Equipped with nothing but the power of your Glare and Gauntlet you must progress through fantastic alien worlds, tackling satisfying platforming challenges and engaging in fast-paced combat. Glare is a game about discovery, new powers and challenges await you on every world.' FROM games WHERE igdb_id = 16563 ON CONFLICT (game_id, language_code) DO NOTHING;
