INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rooftop Freerunning: Leap! Leap!! Leap!!!', 'Leap Leap Leap! is a fast-paced, endless running game where you leap from rooftop to rooftop in a computer simulated world. Download the free stack jumping game and get excited by this fabulous computer simulated world of skyscrapers and surreal colors in parallax effect. On your way, collect cubes and revival points as many as you can to make a long run on top of the buildings. Top the with a high score.' FROM games WHERE igdb_id = 101414 ON CONFLICT (game_id, language_code) DO NOTHING;
