INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beerjeweled', 'Beerjeweled is a homebrew GBA Game that mimics the gameplay of the hugely popular Bejewled game. While replicating the original concept of the Bejeweled, the developers made the decision to replace the typical jewel graphics with alcoholic beverages. The game was developed by, Nuance, Genesis Project & Digital Demolition Krew. They showed the game off at Evoke 2013.' FROM games WHERE igdb_id = 138036 ON CONFLICT (game_id, language_code) DO NOTHING;
