INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Repulze', 'Get ready for a futuristic adrenaline rush from the developers of Reckless Racing. Blast through gravity defying tracks while collecting precious energy boosts to push your speed beyond reason! This futuristic racer puts you in the seat of experimental Repulze hovercraft working as a test pilot for the Man. Well, the Synthetic Man is more accurate. The Synthetics run the corporations.' FROM games WHERE igdb_id = 193703 ON CONFLICT (game_id, language_code) DO NOTHING;
