INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '123 Kids Fun Puzzle Blue', 'Our puzzle for kids game features activities that foster kids creativity and motor skills. 123 Kids Fun Puzzle – puzzle game for toddlers and preschoolers – was extensively tested with kids to ensure its design is as simple as possible and kids can explore the game independently. We hope your kids will love it! Each slider puzzle has 3 different levels of difficulty – 6, 9, or 12 pieces.' FROM games WHERE igdb_id = 89315 ON CONFLICT (game_id, language_code) DO NOTHING;
