INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'There is No Pause Button!', 'Start with up to 999 lives in this fast paced action game where you have only moments to react to what lies ahead! Spikes, dragons, lava pits and false floors are just a few of the obstacles you''ll encounter in your dash to the finish; and when the sweat starts to fall and you need a break, just remember - There is no pause button ...' FROM games WHERE igdb_id = 69374 ON CONFLICT (game_id, language_code) DO NOTHING;
