INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('unemployment-quest', 50803, '2013-10-16', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unemployment Quest', 'UNEMPLOYMENT QUEST! A completely non-epic role playing game! Our protagonist has found that with school over, the oppressive challenge of joblessness is bearing down and crushing all joy in their life! But will you give up? HOPEFULLY NOT! Equip your resume and DO BATTLE with your doubts and fears! Show that you have what it takes to survive in the face of UNCERTAIN FUTURE! This game is not so much a traditional RPG as much as it is an allegory for personal experiences. It is in no way an epic quest as much as it is an exploration of experiences through the tropes and cliches of an RPG.' FROM games WHERE igdb_id = 50803 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 50803 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
