INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '101 Penguin Pets 3D', 'There''s nothing better than a pet penguin! With 101 Penguin Pets 3D, you can have your very own penguin friend to pamper, play with and love, all in amazing 3D. Teach your penguin to breakdance, dress it up in hilarious clothes, and enjoy fun minigames as you take your penguin to the vet, give it a bath, go skiing and more. You''ll never be bored with over 101 penguin friends to groom, pamper, play with and love!' FROM games WHERE igdb_id = 84620 ON CONFLICT (game_id, language_code) DO NOTHING;
