INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Permia - Duels', 'Permia – Duels is a multiplayer online collectible card game that offers real strategy in five minutes. The game is set in prehistoric fantasy world of Permia, which is populated by reptilian beasts, elemental dragons and many strange and unique peoples. Players flip each other''s units to take control of the battleground. Take advantage of the changing special ground types and unit special powers to gain an upper hand against your opponent.' FROM games WHERE igdb_id = 9717 ON CONFLICT (game_id, language_code) DO NOTHING;
