INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DataJack', 'DataJack is a 2D isometric stealth action shooter originally released in 2013. In the not-too-distant future, governments have dissolved and powerful mega-corporations wage covert wars for territory and the control of information. As a freelance mercenary, you will conduct sabotage, assassinations, espionage and ambushes on their behalf to earn a living.' FROM games WHERE igdb_id = 64783 ON CONFLICT (game_id, language_code) DO NOTHING;
