INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aperture Science DS', 'Aperture Science DS, previously known as Portal DS, is a Homebrew version of the popular Portal game series. The project has been released as part of the Neo Flash 2013 coding competition. It features most of the mechanics found in the series and a level editor inspired by Portal 2''s perpetual testing initiative.' FROM games WHERE igdb_id = 165245 ON CONFLICT (game_id, language_code) DO NOTHING;
