INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cross x Beats', 'A mobile music game from Capcom and first in the Crossbeats series that later continued in Arcade games. Two arrows converge on a dots that appear on the screen in time to music. When the arrows cross it is time to touch the dot. The series is produced by former Konami employee Naoki Maeda, famous for composing most of the early music to the hit music game series Dance Dance Revolution. The song list was expanded until end of service, with the final songs list numbering 283 songs.' FROM games WHERE igdb_id = 60817 ON CONFLICT (game_id, language_code) DO NOTHING;
