INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NinJump Rooftops', 'Run for your life! How far can you get? NinJump Rooftops is a fast-paced game where your goal is to jump between rooftops, avoid obstacles, defeat enemies, and stay alive as long as you can. Grab coins & jade crystals along the way to upgrade your ninja abilities. Hit 3 matching enemies in a row for an epic power-up boost. Master the mighty ninja "double jump", where you jump, then jump again in mid-air, defying all laws of physics & logic. Whatever you do, just don''t fall off the roof or let the baddies get you. Stay alive!' FROM games WHERE igdb_id = 324043 ON CONFLICT (game_id, language_code) DO NOTHING;
