INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('popstar-3', 87082, '2013-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/szbfkaruvmgnqwmh6zxh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wqkxtw6mvfvkvgkzkfoa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PopStar 3', 'Beware, once you pop, you can''t stop!  The all time favorite puzzle game was played on millions of touch screens everyday. Now, are you ready to try it on your Mac? For the first time, we are introducing 3 game modes to make it fun for everyone. - Classic mode: meet the target score for each stage  - Timed mode: do your best in 60 seconds, and earn coins  - Moves mode: limited 30 moves, take your time and make the best moves  Choose your preferred control mode, game mode and musics.  Make use of the bonus items to get higher scores and challenge world records.  Share your score to varies social networks. Challenge your friends.  Let''s pop! Let''s have fun.' FROM games WHERE igdb_id = 87082 ON CONFLICT (game_id, language_code) DO NOTHING;
