INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('physicality', 202361, '2013-05-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ryq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch3y3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Physicality', 'Physicality is a Japanese Yume Nikki fangame. You play as Katatsuki, a young boy who shut himself in. Like most fangame protagonists, Katatsuki refuses to leave his room and prefers to explore his dreams instead of reality. Physicality is a very traditional fangame, so many of its aspects are related to events/locations/themes in the original Yume Nikki. It features bright, childish and colorful themes along with dark, violent and bizarre ones. It has three endings.' FROM games WHERE igdb_id = 202361 ON CONFLICT (game_id, language_code) DO NOTHING;
