INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ripple Dot Zero', 'Ripple Dot Zero is an 2D platformer in stylized after other 16 bit games of the 90s, most notably Sonic the Hedgehog and the games it inspired. In it you play as a penguin that just broke free out of a tank tube with the mission to beat the levels and free other penguins in this dystopic future. It was released online by Pixeltruss as a free browser game.' FROM games WHERE igdb_id = 231714 ON CONFLICT (game_id, language_code) DO NOTHING;
