INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yume Gatari', 'Yume Gatari is a traditional Yume Nikki fangame. You play as Netsuki, a boy that refuses to leave his room. Once in the dream world, the player can explore and collect effects. A mini game called SOUL can also by played by interacting with the console.' FROM games WHERE igdb_id = 220078 ON CONFLICT (game_id, language_code) DO NOTHING;
