INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Negaigoto', 'Negaigoto is a Yume Nikki fangame. The game stars Ken, a person living in an old-styled Japanese house with a small garden as opposed to a balcony. Unable to leave his house, he explores a dream world through sleeping in his bed. In the dream world, the nexus contains a single door with 4 possible locations, chosen randomly when the player sleeps.' FROM games WHERE igdb_id = 229395 ON CONFLICT (game_id, language_code) DO NOTHING;
