INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Don 2: The Game', 'Don 2: The Game is a third-person action tie-in game for the 2011 film "Don 2: The King Is Back" developed by Gameshastra and published by Sony Computer Entertainment. The game loosely follows the plot of the film, with Don fighting back against his back-stabbing henchmen, European cartel bosses, and old enemies from the first film. Don 2: The Game is notable for being the last first-party release for the PlayStation 2.' FROM games WHERE igdb_id = 142554 ON CONFLICT (game_id, language_code) DO NOTHING;
