INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tap-beats-jazz', 86917, '2013-06-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/c7rpieujqywld9pqtcak.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nopfgzwgusrqfrurgefg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tap Beats Jazz', 'Tap Beats presents the next installment of it''s hit rhythm game combined with the smoothest genre of all time... Jazz! We have some of the best pieces from the era of Jazz, Blues, and Swing! Tap along with the music, max your combo bar, and score insane points! AWESOME FEATURES CHILL OUT WITH AMAZING GROOVES: Tap along with the music, keep your rhythm and find glory as the ultimate Jazz fan! TONS OF MUSIC: A dozen of the greatest songs you have ever heard! Earn credits based on your performance and unlock the more difficult tracks! INDIVIDUAL RATINGS: Try to achieve three stars on every song to truly master the game! PSYCHEDELIC VISUALS: HD Particle Effects stimulate your retinas while you try to keep up with the beat! The newest and hottest rhythm game is Tap Beats Jazz! The only game bringing you the greatest songs from one of the greatest era''s in music like you''ve never heard them before! Thanks to Kevin MacLeod at Incompetech.com for supplying some of the great Jazz music! See our website for full attributions!' FROM games WHERE igdb_id = 86917 ON CONFLICT (game_id, language_code) DO NOTHING;
