INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney The Little Mermaid: Undersea Treasures!', 'Discover lost items from the mysterious human world above the waves and reveal unique hidden treasures. From the site of an old shipwreck to Ariel''s secret grotto, King Triton''s throne room to the incredible coral canyons. Find items quickly in each scene to earn bonus points and claim your place on the leaderboard.' FROM games WHERE igdb_id = 328255 ON CONFLICT (game_id, language_code) DO NOTHING;
