INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bentley''s Hackpack', 'Bentley''s Hackpack is a standalone minigame compilation developed by Sanzaru Games and published by Sony Computer Entertainment. Released on February 5, 2013, for PlayStation 3 and PlayStation Vita, it coincided with the launch of Sly Cooper: Thieves in Time. In Bentley''s Hackpack, players assume the role of Bentley, the tech-savvy turtle from the Sly Cooper series, accessing three arcade machines—System Cracker, Alter Ego, and Spark Runner—each offering 20 levels with five challenges per level, totaling 300 challenges. Completing these challenges awards tokens, which can be used to unlock 65 prizes in Dimitri''s Prize Gallery, reminiscent of the treasure collection feature in Thieves in Time.' FROM games WHERE igdb_id = 52149 ON CONFLICT (game_id, language_code) DO NOTHING;
